                            className="bg-white/10 hover:bg-white/20 border border-white/10 py-3 rounded-xl text-sm font-bold transition-all disabled:opacity-50 flex items-center justify-center gap-2"
                        >
                            <FileText size={16} /> Word
                        </button>
                        <button 
                            onClick={handlePrintPDF} 
                            disabled={invoices.length === 0} 
                            className="bg-emerald-600 hover:bg-emerald-500 py-3 rounded-xl text-sm font-bold transition-all disabled:opacity-50 shadow-lg shadow-emerald-900/20 flex items-center justify-center gap-2"
                        >
                            <FileDown size={16} /> PDF
                        </button>
                    </div>
                </div>
           </div>

           <ExpensesChart data={chartData} />
        </div>

        <div className="lg:col-span-2 space-y-8">
          <BudgetComparisonChart data={budgetComparisonData} />
          <RecentInvoices invoices={invoices} />
        </div>
      </div>
    </div>
  );

  const ReportsView = () => (
    <div className="space-y-8 animate-fadeIn max-w-6xl mx-auto">
      <div className="bg-white p-10 rounded-[40px] shadow-sm border border-emerald-100 text-center relative overflow-hidden">
        <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-emerald-400 via-blue-500 to-emerald-400"></div>

        <div className="inline-block p-5 bg-emerald-50 rounded-3xl mb-6 shadow-sm">
            <ShieldCheck className="w-12 h-12 text-emerald-600" />
        </div>
        <h2 className="text-3xl font-extrabold text-slate-800 mb-3">{t.reportsTitle}</h2>
        <p className="text-slate-500 max-w-2xl mx-auto mb-10 text-lg">
            {t.reportsSubtitle}
        </p>

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 max-w-3xl mx-auto">
            <button 
                onClick={handleExportWord}
                disabled={invoices.length === 0}
                className="group relative flex flex-col items-center p-6 bg-white border-2 border-slate-100 hover:border-blue-500 rounded-3xl hover:shadow-xl transition-all disabled:opacity-50 disabled:cursor-not-allowed"
            >
                <div className="w-16 h-16 bg-blue-50 text-blue-600 rounded-2xl flex items-center justify-center mb-4 group-hover:scale-110 transition-transform">
                  <FileText size={32} />
                </div>
                <h3 className="text-xl font-bold text-slate-800 mb-2">{t.reportWord}</h3>
                <p className="text-sm text-slate-500">{t.reportWordDesc}</p>
            </button>

            <button 
                onClick={handlePrintPDF}
                disabled={invoices.length === 0}
                className="group relative flex flex-col items-center p-6 bg-white border-2 border-slate-100 hover:border-emerald-500 rounded-3xl hover:shadow-xl transition-all disabled:opacity-50 disabled:cursor-not-allowed"
            >
                <div className="w-16 h-16 bg-emerald-50 text-emerald-600 rounded-2xl flex items-center justify-center mb-4 group-hover:scale-110 transition-transform">
                  <FileDown size={32} />
                </div>
                <h3 className="text-xl font-bold text-slate-800 mb-2">{t.reportPdf}</h3>
                <p className="text-sm text-slate-500">{t.reportPdfDesc}</p>
