      {isSettingsModalOpen && (
        <SettingsModal 
          currentSettings={settings}
          onSave={(newSettings) => setSettings(newSettings)}
          onClose={() => setIsSettingsModalOpen(false)}
        />
      )}

      <ChatBot invoices={invoices} />
    </div>
  );
};

