interface ScannerModalProps {
  onClose: () => void;
  onInvoiceAdded: (invoice: Omit<InvoiceData, 'id'>) => void;
  defaultCurrency: string;
  translations: any;
}

const ScannerModal: React.FC<ScannerModalProps> = ({ onClose, onInvoiceAdded, defaultCurrency, translations: t }) => {
  const [isProcessing, setIsProcessing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    await processFile(file);
  };

  const processFile = async (file: File) => {
    setIsProcessing(true);
    setError(null);
    try {
        const base64Data = await fileToGenerativePart(file);
        // Pass the default currency to the AI service
        const data = await processInvoiceWithGemini(base64Data, defaultCurrency);
        onInvoiceAdded(data);
        onClose();
    } catch (e: any) {
        console.error(e);
        setError(t.scanner.error);
    } finally {
        setIsProcessing(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-emerald-900/40 backdrop-blur-sm">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-md p-6 relative">
        <button 
          onClick={onClose}
          className="absolute left-4 top-4 text-slate-400 hover:text-slate-600 transition-colors"
        >
          <X size={24} />
        </button>

        <div className="text-center mt-4 mb-8">
          <div className="inline-flex items-center justify-center w-16 h-16 bg-emerald-100 text-emerald-600 rounded-full mb-4">
            <Camera size={32} />
          </div>
          <h2 className="text-2xl font-bold text-slate-800">{t.scanner.title}</h2>
          <p className="text-slate-500 text-sm mt-1">{t.scanner.subtitle}</p>
        </div>

        {error && (
            <div className="mb-6 p-4 bg-red-50 text-red-600 rounded-xl text-sm flex items-center gap-2">
                <AlertCircle size={16} className="shrink-0" />
                {error}
            </div>
        )}

        {isProcessing ? (
          <div className="flex flex-col items-center justify-center py-12 space-y-4">
            <Loader2 className="animate-spin text-emerald-600 w-12 h-12" />
            <p className="text-emerald-800 font-medium animate-pulse">{t.scanner.processing}</p>
            <p className="text-xs text-slate-400">{t.scanner.processingDesc}</p>
          </div>
        ) : (
          <div className="space-y-4">
            {/* Capture Input (Hidden standard file input, triggered by buttons) */}
            <input 
                type="file" 
                accept="image/*" 
                className="hidden" 
                ref={fileInputRef}
                onChange={handleFileChange}
            />

            <button 
                onClick={() => fileInputRef.current?.click()}
                className="w-full py-4 border-2 border-dashed border-emerald-200 rounded-xl bg-emerald-50/50 hover:bg-emerald-50 text-emerald-700 font-medium transition-colors flex flex-col items-center gap-2 group"
            >
                <Upload className="group-hover:scale-110 transition-transform" />
                <span>{t.scanner.uploadBtn}</span>
            </button>

            <p className="text-xs text-center text-slate-400">
                {t.scanner.supportText.replace('{curr}', defaultCurrency)}
            </p>
          </div>
        )}
      </div>
    </div>
  );
};

export default ScannerModal;

import React, { useState } from 'react';
import { X, Save, Calculator, Globe, CreditCard } from 'lucide-react';
import { ExpenseCategory, AppSettings, CURRENCIES, CATEGORY_MAPPING } from '../types';

interface SettingsModalProps {
  currentSettings: AppSettings;
  onSave: (settings: AppSettings) => void;
  onClose: () => void;
  translations: any;
  language: string;
}

type Tab = 'general' | 'budgets';

const SettingsModal: React.FC<SettingsModalProps> = ({ currentSettings, onSave, onClose, translations: t, language }) => {
  const [activeTab, setActiveTab] = useState<Tab>('general');
  const [settings, setSettings] = useState<AppSettings>(currentSettings);

  const handleBudgetChange = (category: ExpenseCategory, value: string) => {
    const numValue = parseFloat(value);
    setSettings(prev => ({
      ...prev,
      budgets: {
          ...prev.budgets,
          [category]: isNaN(numValue) ? 0 : numValue
      }
    }));
  };

  const handleCurrencyChange = (code: string) => {
      setSettings(prev => ({
          ...prev,
          defaultCurrency: code
      }));
  };

  const handleSave = () => {
    onSave(settings);
    onClose();
  };

  const getCategoryLabel = (cat: string) => {
    return language === 'en' && CATEGORY_MAPPING[cat] ? CATEGORY_MAPPING[cat] : cat;
  };

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-lg p-0 relative max-h-[90vh] overflow-hidden flex flex-col">
        {/* Header */}
        <div className="p-6 pb-2 border-b border-slate-100">
            <button 
                onClick={onClose}
                className="absolute left-4 top-4 text-slate-400 hover:text-slate-600 transition-colors"
            >
                <X size={24} />
            </button>
            <h2 className="text-2xl font-bold text-slate-800 text-center">{t.settings.title}</h2>
        </div>

        {/* Tabs */}
        <div className="flex border-b border-slate-100">
            <button 
                onClick={() => setActiveTab('general')}
                className={`flex-1 py-4 text-sm font-bold flex items-center justify-center gap-2 transition-colors ${activeTab === 'general' ? 'text-emerald-600 border-b-2 border-emerald-600 bg-emerald-50/50' : 'text-slate-500 hover:bg-slate-50'}`}
            >
                <Globe size={18} />
                <span>{t.settings.tabGeneral}</span>
            </button>
            <button 
                onClick={() => setActiveTab('budgets')}
                className={`flex-1 py-4 text-sm font-bold flex items-center justify-center gap-2 transition-colors ${activeTab === 'budgets' ? 'text-blue-600 border-b-2 border-blue-600 bg-blue-50/50' : 'text-slate-500 hover:bg-slate-50'}`}
            >
                <Calculator size={18} />
                <span>{t.settings.tabBudgets}</span>
            </button>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-6">
            {activeTab === 'general' && (
                <div className="space-y-6">
                    <div>
                        <label className="block text-slate-700 font-bold mb-3 flex items-center gap-2">
                            <CreditCard size={18} className="text-emerald-500" />
                            {t.settings.defaultCurrency}
                        </label>
                        <p className="text-sm text-slate-500 mb-4">
                            {t.settings.currencyDesc}
                        </p>
                        <div className="grid grid-cols-2 gap-3">
                            {CURRENCIES.map((curr) => (
                                <button
                                    key={curr.code}
                                    onClick={() => handleCurrencyChange(curr.code)}
                                    className={`p-3 rounded-xl border text-right transition-all ${
                                        settings.defaultCurrency === curr.code 
                                        ? 'border-emerald-500 bg-emerald-50 text-emerald-800 ring-1 ring-emerald-500' 
                                        : 'border-slate-200 text-slate-600 hover:border-emerald-200'
                                    }`}
                                >
                                    <div className="font-bold flex justify-between">
                                        <span>{language === 'ar' ? curr.nameAr : curr.nameEn}</span>
                                        <span className="font-mono text-sm opacity-50">{curr.code}</span>
                                    </div>
                                    <div className="text-sm opacity-70 mt-1">{curr.symbol}</div>
                                </button>
                            ))}
                        </div>
                    </div>
                </div>
            )}

            {activeTab === 'budgets' && (
                <div className="space-y-4">
                     <p className="text-sm text-slate-500 mb-2">{t.settings.budgetDesc}</p>
                     {Object.values(ExpenseCategory).map((category) => (
                        <div key={category} className="flex items-center gap-4">
                        <label className="w-1/2 text-sm font-medium text-slate-700">{getCategoryLabel(category)}</label>
                        <div className="relative w-1/2">
                            <input
                            type="number"
                            min="0"
                            step="10"
                            value={settings.budgets[category] || ''}
                            onChange={(e) => handleBudgetChange(category, e.target.value)}
                            placeholder="0.000"
                            className="w-full px-4 py-2 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none text-left ltr"
                            dir="ltr"
                            />
                            <span className="absolute right-3 top-1/2 -translate-y-1/2 text-xs text-slate-400 font-medium">{t.settings.currencyUnit}</span>
                        </div>
                        </div>
                    ))}
                </div>
            )}
        </div>

        {/* Footer */}
        <div className="p-6 pt-0">
            <button 
            onClick={handleSave}
            className="w-full py-3 bg-slate-900 hover:bg-slate-800 text-white rounded-xl font-bold shadow-lg shadow-slate-200 transition-all flex items-center justify-center gap-2"
            >
            <Save size={20} />
            <span>{t.settings.saveBtn}</span>
            </button>
        </div>
      </div>
    </div>
  );
};

export default SettingsModal;

import React from 'react';
import { ExpenseCategory, BudgetLimits, CATEGORY_MAPPING } from '../types';
import { AlertTriangle, CheckCircle } from 'lucide-react';

interface BudgetStatusProps {
  budgets: BudgetLimits;
  currentSpending: Record<string, number>;
  translations: any;
  language: string;
}

const BudgetStatus: React.FC<BudgetStatusProps> = ({ budgets, currentSpending, translations: t, language }) => {
  // Filter categories that actually have a budget set
  const activeBudgets = Object.entries(budgets)
    .filter(([_, limit]) => typeof limit === 'number' && limit > 0) as [string, number][];

  if (activeBudgets.length === 0) {
    return (
      <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 h-full flex flex-col items-center justify-center text-center">
        <div className="p-3 bg-slate-100 rounded-full mb-3 text-slate-400">
            <AlertTriangle size={24} />
        </div>
        <h3 className="text-slate-600 font-bold mb-1">{t.budgetStatus.noBudgetTitle}</h3>
        <p className="text-xs text-slate-400">{t.budgetStatus.noBudgetDesc}</p>
      </div>
    );
  }

  const getCategoryLabel = (cat: string) => {
    return language === 'en' && CATEGORY_MAPPING[cat] ? CATEGORY_MAPPING[cat] : cat;
  };

  return (
    <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 h-full overflow-y-auto">
      <h2 className="text-xl font-bold text-slate-800 mb-4 flex items-center gap-2">
        <span>{t.budgetStatus.title}</span>
        <span className="text-xs font-normal text-slate-400 bg-slate-50 px-2 py-1 rounded-full">{t.budgetStatus.monthly}</span>
      </h2>

      <div className="space-y-6">
        {activeBudgets.map(([cat, limit]) => {
          const category = cat as ExpenseCategory;
          const spent = currentSpending[category] || 0;
          const percentage = Math.min((spent / limit) * 100, 100);
          const isOverBudget = spent > limit;

          return (
            <div key={category}>
              <div className="flex justify-between items-end mb-1">
                <span className="text-sm font-medium text-slate-700">{getCategoryLabel(category)}</span>
                <div className="text-xs font-mono" dir="ltr">
                  <span className={isOverBudget ? "text-red-600 font-bold" : "text-slate-600"}>
                    {spent.toFixed(1)}
                  </span>
                  <span className="text-slate-400"> / {limit.toFixed(1)} {t.stats.currency}</span>
                </div>
              </div>

              <div className="relative h-2.5 w-full bg-slate-100 rounded-full overflow-hidden">
                <div 
                  className={`absolute top-0 right-0 h-full rounded-full transition-all duration-500 ${
                    isOverBudget ? 'bg-red-500' : percentage > 80 ? 'bg-amber-400' : 'bg-emerald-500'
                  }`}
                  style={{ width: `${percentage}%` }}
                />
              </div>

              {isOverBudget && (
                <div className="mt-1 flex items-center gap-1 text-[10px] text-red-500 font-medium animate-pulse">
                  <AlertTriangle size={10} />
                  <span>{t.budgetStatus.overBudget}</span>
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default BudgetStatus;

