        <div className="relative z-10">
            <div className="inline-flex items-center gap-2 bg-white/80 border border-slate-200 backdrop-blur-sm px-4 py-1.5 rounded-full text-sm font-semibold text-slate-600 mb-6 shadow-sm">
                <BrainCircuit size={16} className="text-emerald-500" />
                <span>{t.aiBadge}</span>
            </div>

            <h2 className="text-5xl md:text-7xl font-extrabold text-slate-800 mb-6 leading-tight tracking-tight">
                {t.heroTitle}
            </h2>

            <p className="text-xl text-slate-500 max-w-2xl mx-auto mb-10 leading-relaxed">
                {t.heroSubtitle}
            </p>

            <div className="flex flex-col sm:flex-row justify-center gap-4">
                <button 
                onClick={() => setActiveView('dashboard')}
                className="bg-slate-900 text-white px-10 py-4 rounded-2xl font-bold hover:bg-slate-800 transition-all shadow-xl shadow-slate-200 flex items-center justify-center gap-3 group"
                >
                <span>{t.btnDashboard}</span>
                {language === 'ar' ? <ChevronRight className="group-hover:-translate-x-1 transition-transform" /> : <ChevronRight className="group-hover:translate-x-1 transition-transform" />}
                </button>
                <button 
                onClick={() => setIsScanning(true)}
                className="bg-emerald-500 text-white border border-emerald-400 px-10 py-4 rounded-2xl font-bold hover:bg-emerald-400 transition-all flex items-center justify-center gap-3 shadow-xl shadow-emerald-200"
                >
                <ScanLine size={22} />
                <span>{t.btnScan}</span>
                </button>
            </div>
        </div>
      </div>

      {/* Feature Grid */}
      <div className={`mt-16 grid grid-cols-1 md:grid-cols-3 gap-6 w-full max-w-5xl ${language === 'ar' ? 'text-right' : 'text-left'}`}>
        <div className="bg-white p-8 rounded-3xl shadow-lg border border-slate-100 hover:border-emerald-200 transition-colors group">
            <div className="w-14 h-14 bg-emerald-50 text-emerald-600 rounded-2xl flex items-center justify-center mb-6 group-hover:scale-110 transition-transform">
                <Camera size={28} />
            </div>
            <h3 className="font-bold text-slate-800 text-xl mb-3">{t.step1Title}</h3>
            <p className="text-slate-500 leading-relaxed">{t.step1Desc}</p>
        </div>
        <div className="bg-white p-8 rounded-3xl shadow-lg border border-slate-100 hover:border-blue-200 transition-colors group">
            <div className="w-14 h-14 bg-blue-50 text-blue-600 rounded-2xl flex items-center justify-center mb-6 group-hover:scale-110 transition-transform">
                <BrainCircuit size={28} />
            </div>
            <h3 className="font-bold text-slate-800 text-xl mb-3">{t.step2Title}</h3>
            <p className="text-slate-500 leading-relaxed">{t.step2Desc}</p>
        </div>
        <div className="bg-white p-8 rounded-3xl shadow-lg border border-slate-100 hover:border-purple-200 transition-colors group">
            <div className="w-14 h-14 bg-purple-50 text-purple-600 rounded-2xl flex items-center justify-center mb-6 group-hover:scale-110 transition-transform">
                <FileText size={28} />
            </div>
            <h3 className="font-bold text-slate-800 text-xl mb-3">{t.step3Title}</h3>
            <p className="text-slate-500 leading-relaxed">{t.step3Desc}</p>
        </div>
      </div>
    </div>
  );

  const DashboardView = () => (
    <div className="space-y-8 animate-fadeIn pb-10">
      <div className="flex justify-between items-end">
        <div>
           <h2 className="text-3xl font-extrabold text-slate-800 flex items-center gap-3">
             <LayoutDashboard className="text-emerald-600" size={32} />
             {t.dashboardTitle}
           </h2>
           <p className="text-slate-500 mt-2 text-lg">{t.dashboardSubtitle}</p>
        </div>
      </div>

      {budgetAlerts.length > 0 && (
          <div className="bg-red-50 border border-red-200 text-red-700 px-6 py-4 rounded-2xl flex items-start gap-4 shadow-sm animate-pulse">
            <div className="bg-red-100 p-2 rounded-lg">
                <AlertTriangle className="shrink-0 text-red-600" size={24} />
            </div>
            <div>
              <p className="font-bold text-lg">{t.budgetAlertTitle}</p>
              <ul className="list-disc list-inside text-sm mt-2 space-y-1 opacity-90">
                {budgetAlerts.map((alert, idx) => (
                    <li key={idx}>{alert}</li>
                ))}
              </ul>
            </div>
          </div>
      )}

      <StatsCards stats={stats} translations={t} />

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-1 space-y-8">
           {/* Budget Status Widget */}
           <div className="h-[400px]">
             <BudgetStatus budgets={settings.budgets} currentSpending={spendingByCategory} translations={t} language={language} />
           </div>

           {/* Export Shortcut Card */}
           <div className="relative bg-slate-900 rounded-3xl p-8 text-white shadow-2xl overflow-hidden">
                <div className="absolute top-0 left-0 w-32 h-32 bg-emerald-500/20 rounded-full blur-3xl -ml-10 -mt-10"></div>
                <div className="absolute bottom-0 right-0 w-32 h-32 bg-blue-500/20 rounded-full blur-3xl -mr-10 -mb-10"></div>

                <div className="relative z-10">
                    <div className="flex items-center gap-3 mb-4">
                        <div className="bg-white/10 p-2.5 rounded-xl border border-white/10 backdrop-blur-md">
                            <Zap size={24} className="text-yellow-300" />
                        </div>
                        <h3 className="font-bold text-xl">{t.quickActions}</h3>
                    </div>
                    <p className="text-slate-300 text-sm mb-6 leading-relaxed">
                        {t.exportDesc}
                    </p>
                    <div className="grid grid-cols-2 gap-4">
                        <button 
                            onClick={handleExportWord} 
                            disabled={invoices.length === 0} 
                            className="bg-white/10 hover:bg-white/20 border border-white/10 py-3 rounded-xl text-sm font-bold transition-all disabled:opacity-50 flex items-center justify-center gap-2"
                        >
                            <FileText size={16} /> Word
                        </button>
                        <button 
                            onClick={handlePrintPDF} 
                            disabled={invoices.length === 0} 
                            className="bg-emerald-600 hover:bg-emerald-500 py-3 rounded-xl text-sm font-bold transition-all disabled:opacity-50 shadow-lg shadow-emerald-900/20 flex items-center justify-center gap-2"
                        >
                            <FileDown size={16} /> PDF
                        </button>
                    </div>
                </div>
           </div>

           <ExpensesChart data={chartData} translations={t} />
        </div>

        <div className="lg:col-span-2 space-y-8">
          <BudgetComparisonChart data={budgetComparisonData} translations={t} />
          <RecentInvoices invoices={invoices} translations={t} language={language} />
        </div>
      </div>
    </div>
  );

  const ReportsView = () => (
    <div className="space-y-8 animate-fadeIn max-w-6xl mx-auto">
      <div className="bg-white p-10 rounded-[40px] shadow-sm border border-emerald-100 text-center relative overflow-hidden">
        <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-emerald-400 via-blue-500 to-emerald-400"></div>

        <div className="inline-block p-5 bg-emerald-50 rounded-3xl mb-6 shadow-sm">
            <ShieldCheck className="w-12 h-12 text-emerald-600" />
        </div>
        <h2 className="text-3xl font-extrabold text-slate-800 mb-3">{t.reportsTitle}</h2>
        <p className="text-slate-500 max-w-2xl mx-auto mb-10 text-lg">
            {t.reportsSubtitle}
        </p>

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 max-w-3xl mx-auto">
            <button 
                onClick={handleExportWord}
                disabled={invoices.length === 0}
