export const generateWordDocument = async (invoices: InvoiceData[], stats: DashboardStats) => {
  const date = new Date().toLocaleDateString('ar-OM');

  // Helper to create Arabic text run
  const arabicText = (text: string, bold: boolean = false, size: number = 24) => 
    new TextRun({
      text: text,
      font: "Times New Roman", // Standard for Arabic in Word
      bold: bold,
      size: size, // Half-points (24 = 12pt)
      rightToLeft: true,
    });

  // Table Header
  const tableHeader = new TableRow({
    tableHeader: true,
    children: [
      "الحالة", "العملة الأصلية", "الإجمالي (ر.ع)", "الضريبة (5%)", "التصنيف", "المورد", "التاريخ"
    ].map(text => 
      new TableCell({
        width: { size: 100 / 7, type: WidthType.PERCENTAGE },
        shading: { fill: "E0F2F1" }, // Emerald-50 ish
        children: [
            new Paragraph({
                alignment: AlignmentType.CENTER,
                bidirectional: true,
                children: [arabicText(text, true, 22)]
            })
        ],
        verticalAlign: "center",
      })
    )
  });

  // Table Rows
  const tableRows = invoices.map(inv => 
    new TableRow({
      children: [
        new TableCell({
            children: [new Paragraph({ alignment: AlignmentType.CENTER, bidirectional: true, children: [arabicText(inv.vatStatus)] })]
        }),
        new TableCell({
            children: [
                new Paragraph({ alignment: AlignmentType.CENTER, children: [
                    new TextRun({ text: inv.originalAmount?.toFixed(2) || inv.totalAmount.toFixed(3), bold: false }),
                    new TextRun({ text: ` ${inv.currency || 'OMR'}`, size: 16 })
                ] })
            ]
        }),
        new TableCell({
            children: [new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: inv.totalAmount.toFixed(3), bold: true })] })]
        }),
        new TableCell({
            children: [new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: inv.vatAmount.toFixed(3), color: "DC2626" })] })]
        }),
        new TableCell({
            children: [new Paragraph({ alignment: AlignmentType.CENTER, bidirectional: true, children: [arabicText(inv.category)] })]
        }),
        new TableCell({
            children: [new Paragraph({ alignment: AlignmentType.CENTER, bidirectional: true, children: [arabicText(inv.vendorName, true)] })]
        }),
        new TableCell({
            children: [new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun(inv.date)] })]
        }),
      ],
    })
  );

  const doc = new Document({
    sections: [{
      properties: {},
      children: [
        // Title
        new Paragraph({
            alignment: AlignmentType.CENTER,
            bidirectional: true,
            heading: HeadingLevel.TITLE,
            children: [
                arabicText("فينيك الذكي", true, 48),
            ],
            spacing: { after: 200 }
        }),

        new Paragraph({
            alignment: AlignmentType.CENTER,
            bidirectional: true,
            children: [
                arabicText(`تقرير المصروفات - ${date}`, false, 32),
            ],
            spacing: { after: 400 }
        }),

        // Summary Section
        new Paragraph({
            bidirectional: true,
            children: [arabicText("ملخص مالي:", true, 28)],
            spacing: { after: 200 }
        }),
        new Paragraph({
            bidirectional: true,
            bullet: { level: 0 },
            children: [
                arabicText(`عدد الفواتير: ${stats.invoiceCount}`),
            ]
        }),
        new Paragraph({
            bidirectional: true,
            bullet: { level: 0 },
            children: [
                arabicText(`إجمالي المصروفات: ${stats.totalSpend.toFixed(3)} ر.ع`),
            ]
        }),
        new Paragraph({
            bidirectional: true,
            bullet: { level: 0 },
            children: [
                arabicText(`إجمالي الضريبة المستردة: ${stats.totalVat.toFixed(3)} ر.ع`),
            ],
            spacing: { after: 400 }
        }),

        // The Table
        new Table({
            layout: TableLayoutType.FIXED,
            width: { size: 100, type: WidthType.PERCENTAGE },
            rows: [tableHeader, ...tableRows],
        }),

        // Footer note
        new Paragraph({
            alignment: AlignmentType.CENTER,
            bidirectional: true,
            children: [
                arabicText("تم إنشاء هذا التقرير تلقائياً بواسطة نظام فينيك الذكي", false, 18),
            ],
            spacing: { before: 600 }
        })
      ],
    }],
  });

  const blob = await Packer.toBlob(doc);
  FileSaver.saveAs(blob, `تقرير-فينيك-الذكي-${date.replace(/\//g, '-')}.docx`);
};

