import React, { useState, useRef } from 'react';
import { X, Upload, Camera, Loader2, AlertCircle } from 'lucide-react';
import { fileToGenerativePart, processInvoiceWithGemini } from '../services/geminiService';
import { InvoiceData } from '../types';

interface ScannerModalProps {
  onClose: () => void;
  onInvoiceAdded: (invoice: Omit<InvoiceData, 'id'>) => void;
  defaultCurrency: string;
  translations: any;
}

const ScannerModal: React.FC<ScannerModalProps> = ({ onClose, onInvoiceAdded, defaultCurrency, translations: t }) => {
  const [isProcessing, setIsProcessing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    await processFile(file);
  };

  const processFile = async (file: File) => {
    setIsProcessing(true);
    setError(null);
    try {
        const base64Data = await fileToGenerativePart(file);
        // Pass the default currency to the AI service
        const data = await processInvoiceWithGemini(base64Data, defaultCurrency);
        onInvoiceAdded(data);
        onClose();
    } catch (e: any) {
        console.error(e);
        setError(t.scanner.error);
    } finally {
        setIsProcessing(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-emerald-900/40 backdrop-blur-sm">
      <div className="bg-white dark:bg-slate-900 rounded-3xl shadow-2xl w-full max-w-md p-6 relative transition-colors">
        <button 
          onClick={onClose}
          className="absolute left-4 top-4 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 transition-colors"
        >
          <X size={24} />
        </button>

        <div className="text-center mt-4 mb-8">
