        )}

        {isProcessing ? (
          <div className="flex flex-col items-center justify-center py-12 space-y-4">
            <Loader2 className="animate-spin text-emerald-600 dark:text-emerald-400 w-12 h-12" />
            <p className="text-emerald-800 dark:text-emerald-300 font-medium animate-pulse">{t.scanner.processing}</p>
            <p className="text-xs text-slate-400">{t.scanner.processingDesc}</p>
          </div>
        ) : (
          <div className="space-y-4">
            {/* Capture Input (Hidden standard file input, triggered by buttons) */}
            <input 
                type="file" 
                accept="image/*" 
                className="hidden" 
                ref={fileInputRef}
                onChange={handleFileChange}
            />

            <button 
                onClick={() => fileInputRef.current?.click()}
                className="w-full py-4 border-2 border-dashed border-emerald-200 dark:border-emerald-700 rounded-xl bg-emerald-50/50 dark:bg-emerald-900/10 hover:bg-emerald-50 dark:hover:bg-emerald-900/20 text-emerald-700 dark:text-emerald-300 font-medium transition-colors flex flex-col items-center gap-2 group"
            >
