                    <button 
                        onClick={() => setLanguage('ar')}
                        className={`px-2 py-1 rounded-md text-xs font-bold transition-all ${language === 'ar' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-400 hover:text-white'}`}
                    >
                        عربي
