const App: React.FC = () => {
  const [activeView, setActiveView] = useState<ViewState>('home');
  const [isScanning, setIsScanning] = useState(false);
  const [isSettingsModalOpen, setIsSettingsModalOpen] = useState(false);
  const [isSubscriptionModalOpen, setIsSubscriptionModalOpen] = useState(false);

  // User Authentication State
  const [user, setUser] = useState<UserProfile | null>(() => {
     try {
         const savedUser = localStorage.getItem('fyniq_user');
         return savedUser ? JSON.parse(savedUser) : null;
     } catch(e) { return null; }
  });

  // Theme State
  const [theme, setTheme] = useState<Theme>(() => {
    if (typeof window !== 'undefined') {
      const saved = localStorage.getItem('app_theme');
      if (saved) return saved as Theme;
      return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
    }
    return 'light';
  });

  // Language State
  const [language, setLanguage] = useState<Language>(() => {
     return (localStorage.getItem('app_language') as Language) || 'ar';
  });

  // Handle Theme Side Effects
  useEffect(() => {
    localStorage.setItem('app_theme', theme);
    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [theme]);

  // Handle Language Side Effects
  useEffect(() => {
    localStorage.setItem('app_language', language);
    document.documentElement.lang = language;
    document.documentElement.dir = language === 'ar' ? 'rtl' : 'ltr';
  }, [language]);

  const t = TRANSLATIONS[language];
  const isDarkMode = theme === 'dark';

  // Initialize invoices from localStorage
  const [invoices, setInvoices] = useState<InvoiceData[]>(() => {
    try {
      const saved = localStorage.getItem('omani_accountant_invoices');
      return saved ? JSON.parse(saved) : [];
    } catch (e) {
      console.error("Failed to load invoices", e);
      return [];
    }
  });

  // Initialize Settings
  const [settings, setSettings] = useState<AppSettings>(() => {
    try {
      const saved = localStorage.getItem('omani_accountant_settings');
      if (saved) {
          return JSON.parse(saved);
      }
      const legacyBudgets = localStorage.getItem('omani_accountant_budgets');
      return {
          defaultCurrency: 'OMR',
          budgets: legacyBudgets ? JSON.parse(legacyBudgets) : {}
      };
    } catch (e) {
      return { defaultCurrency: 'OMR', budgets: {} };
    }
  });

  // Save invoices when changed
  useEffect(() => {
    localStorage.setItem('omani_accountant_invoices', JSON.stringify(invoices));
  }, [invoices]);

  // Save settings when changed
  useEffect(() => {
    localStorage.setItem('omani_accountant_settings', JSON.stringify(settings));
    localStorage.setItem('omani_accountant_budgets', JSON.stringify(settings.budgets));
  }, [settings]);

  // Handle User Login
  const handleLogin = (profile: UserProfile) => {
      // Initialize Default Subscription for new users or existing legacy users
      const profileWithSub: UserProfile = {
          ...profile,
          subscription: profile.subscription || {
              plan: 'FREE',
              cycle: 'MONTHLY',
              usageCount: invoices.length, // Sync with existing invoice count logic for now
              limit: 30,
              renewalDate: new Date(new Date().setMonth(new Date().getMonth() + 1)).toISOString()
          }
      };

      setUser(profileWithSub);
      localStorage.setItem('fyniq_user', JSON.stringify(profileWithSub));
      setActiveView('dashboard'); // Auto redirect to dashboard on login
  };

  // Handle Profile Update
  const handleUpdateProfile = (updatedProfile: UserProfile) => {
    setUser(updatedProfile);
    localStorage.setItem('fyniq_user', JSON.stringify(updatedProfile));
  };

  // Handle Plan Upgrade
  const handleUpgrade = (plan: PlanType, cycle: 'MONTHLY' | 'YEARLY') => {
      if (!user) return;

      const limits: Record<PlanType, number> = {
          'FREE': 30,
          'STANDARD': 70,
          'ENTERPRISE': -1
      };

      const updatedUser: UserProfile = {
          ...user,
          subscription: {
              ...user.subscription,
              plan: plan,
              cycle: cycle,
              limit: limits[plan],
              // In real app, reset usage on cycle change or keep it? Keeping for now.
          }
      };
      setUser(updatedUser);
      localStorage.setItem('fyniq_user', JSON.stringify(updatedUser));
      setIsSubscriptionModalOpen(false);
      alert(`Successfully upgraded to ${plan} Plan!`);
  };

  // Handle User Logout
  const handleLogout = () => {
      setUser(null);
      localStorage.removeItem('fyniq_user');
      setActiveView('home');
  };

  // Derived State
  const stats: DashboardStats = useMemo(() => {
    return invoices.reduce((acc, curr) => ({
      totalSpend: acc.totalSpend + curr.totalAmount,
      totalVat: acc.totalVat + curr.vatAmount,
      invoiceCount: acc.invoiceCount + 1
    }), { totalSpend: 0, totalVat: 0, invoiceCount: 0 });
  }, [invoices]);

  const spendingByCategory = useMemo(() => {
    return invoices.reduce((acc, curr) => {
      acc[curr.category] = (acc[curr.category] || 0) + curr.totalAmount;
      return acc;
    }, {} as Record<string, number>);
  }, [invoices]);

  // Helper to get translated category name
  const getCategoryName = (cat: string) => {
      return language === 'en' && CATEGORY_MAPPING[cat] ? CATEGORY_MAPPING[cat] : cat;
  };

  const chartData: ChartData[] = useMemo(() => {
    const colors: Record<string, string> = {
      [ExpenseCategory.COGS]: '#059669',
      [ExpenseCategory.OPERATING]: '#3b82f6',
      [ExpenseCategory.SALARY]: '#8b5cf6',
      [ExpenseCategory.MARKETING]: '#f59e0b',
      [ExpenseCategory.ADMIN]: '#64748b',
      [ExpenseCategory.ASSETS]: '#0ea5e9',
      [ExpenseCategory.UTILITIES]: '#ec4899',
    };

    return Object.entries(spendingByCategory).map(([name, value]) => ({
      name: getCategoryName(name), // Translate name
      value,
      fill: colors[name] || '#cbd5e1'
    }));
  }, [spendingByCategory, language]);

  const budgetComparisonData = useMemo(() => {
    return Object.values(ExpenseCategory).map(cat => ({
      name: getCategoryName(cat), // Translate name
      actual: spendingByCategory[cat] || 0,
      budget: settings.budgets[cat] || 0
    })).filter(item => item.actual > 0 || item.budget > 0);
  }, [spendingByCategory, settings.budgets, language]);

  const budgetAlerts = useMemo(() => {
    const alerts: string[] = [];
    Object.entries(settings.budgets).forEach(([cat, limit]) => {
        if (limit && spendingByCategory[cat] > limit) {
            const catName = getCategoryName(cat);
            const msg = language === 'ar' 
                ? `تنبيه: لقد تجاوزت موازنة "${catName}" المحددة (${limit} ر.ع)`
                : `Alert: You exceeded budget for "${catName}" (${limit} OMR)`;
            alerts.push(msg);
        }
    });
    return alerts;
  }, [settings.budgets, spendingByCategory, language]);

  const handleScanClick = () => {
    if (!user) return;

    // Check Limits
    const limit = user.subscription.limit;
    const current = user.subscription.usageCount;

    if (limit !== -1 && current >= limit) {
        setIsSubscriptionModalOpen(true);
        // Optional: show a specific alert inside modal or before opening
        return;
    }

    setIsScanning(true);
  };

  const handleInvoiceAdded = (newInvoiceData: Omit<InvoiceData, 'id'>) => {
    const newInvoice: InvoiceData = {
      ...newInvoiceData,
      id: crypto.randomUUID(),
    };
    setInvoices(prev => [newInvoice, ...prev]);

    // Increment Usage Logic
    if (user) {
        const updatedUser = {
            ...user,
            subscription: {
                ...user.subscription,
                usageCount: user.subscription.usageCount + 1
            }
        };
        setUser(updatedUser);
        localStorage.setItem('fyniq_user', JSON.stringify(updatedUser));
    }

    setActiveView('dashboard');
  };

  const handleExportWord = () => {
    generateWordDocument(invoices, stats);
  };

  const handlePrintPDF = () => {
    window.print();
  };

  // --- Views Components ---

  const HomeView = () => (
    <div className="flex flex-col items-center justify-center py-10 text-center animate-fadeIn">
      {/* Hero Section */}
      <div className="relative w-full max-w-5xl mx-auto bg-gradient-to-b from-white to-slate-50 dark:from-slate-800 dark:to-slate-900 rounded-[40px] p-8 md:p-16 shadow-2xl shadow-slate-200 dark:shadow-slate-900 border border-white dark:border-slate-700 overflow-hidden transition-all">

        {/* Decorative Background Elements */}
        <div className="absolute top-0 right-0 w-96 h-96 bg-emerald-100/50 dark:bg-emerald-500/10 rounded-full blur-3xl -mr-20 -mt-20"></div>
        <div className="absolute bottom-0 left-0 w-96 h-96 bg-blue-100/50 dark:bg-blue-500/10 rounded-full blur-3xl -ml-20 -mb-20"></div>

        <div className="relative z-10">
            <div className="inline-flex items-center gap-2 bg-white/80 dark:bg-slate-800/80 border border-slate-200 dark:border-slate-700 backdrop-blur-sm px-4 py-1.5 rounded-full text-sm font-semibold text-slate-600 dark:text-slate-300 mb-6 shadow-sm">
                <BrainCircuit size={16} className="text-emerald-500" />
                <span>{t.aiBadge}</span>
            </div>

            <h2 className="text-5xl md:text-7xl font-extrabold text-slate-800 dark:text-white mb-6 leading-tight tracking-tight">
                {t.heroTitle}
            </h2>

            <p className="text-xl text-slate-500 dark:text-slate-400 max-w-2xl mx-auto mb-10 leading-relaxed">
                {t.heroSubtitle}
            </p>

            <div className="flex flex-col sm:flex-row justify-center gap-4">
                <button 
                onClick={() => setActiveView('dashboard')}
                className="bg-slate-900 dark:bg-white text-white dark:text-slate-900 px-10 py-4 rounded-2xl font-bold hover:bg-slate-800 dark:hover:bg-slate-200 transition-all shadow-xl shadow-slate-200 dark:shadow-slate-900/50 flex items-center justify-center gap-3 group"
                >
                <span>{t.btnDashboard}</span>
                {language === 'ar' ? <ChevronRight className="group-hover:-translate-x-1 transition-transform" /> : <ChevronRight className="group-hover:translate-x-1 transition-transform" />}
                </button>
                <button 
                onClick={handleScanClick}
                className="bg-emerald-500 text-white border border-emerald-400 px-10 py-4 rounded-2xl font-bold hover:bg-emerald-400 transition-all flex items-center justify-center gap-3 shadow-xl shadow-emerald-200 dark:shadow-emerald-900/50"
                >
                <ScanLine size={22} />
                <span>{t.btnScan}</span>
                </button>
            </div>
        </div>
      </div>

      {/* Feature Grid */}
      <div className={`mt-16 grid grid-cols-1 md:grid-cols-3 gap-6 w-full max-w-5xl ${language === 'ar' ? 'text-right' : 'text-left'}`}>
        <div className="bg-white dark:bg-slate-800 p-8 rounded-3xl shadow-lg border border-slate-100 dark:border-slate-700 hover:border-emerald-200 dark:hover:border-emerald-700 transition-colors group">
            <div className="w-14 h-14 bg-emerald-50 dark:bg-emerald-900/30 text-emerald-600 dark:text-emerald-400 rounded-2xl flex items-center justify-center mb-6 group-hover:scale-110 transition-transform">
                <Camera size={28} />
            </div>
            <h3 className="font-bold text-slate-800 dark:text-white text-xl mb-3">{t.step1Title}</h3>
            <p className="text-slate-500 dark:text-slate-400 leading-relaxed">{t.step1Desc}</p>
        </div>
        <div className="bg-white dark:bg-slate-800 p-8 rounded-3xl shadow-lg border border-slate-100 dark:border-slate-700 hover:border-blue-200 dark:hover:border-blue-700 transition-colors group">
            <div className="w-14 h-14 bg-blue-50 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 rounded-2xl flex items-center justify-center mb-6 group-hover:scale-110 transition-transform">
                <BrainCircuit size={28} />
            </div>
            <h3 className="font-bold text-slate-800 dark:text-white text-xl mb-3">{t.step2Title}</h3>
            <p className="text-slate-500 dark:text-slate-400 leading-relaxed">{t.step2Desc}</p>
        </div>
        <div className="bg-white dark:bg-slate-800 p-8 rounded-3xl shadow-lg border border-slate-100 dark:border-slate-700 hover:border-purple-200 dark:hover:border-purple-700 transition-colors group">
            <div className="w-14 h-14 bg-purple-50 dark:bg-purple-900/30 text-purple-600 dark:text-purple-400 rounded-2xl flex items-center justify-center mb-6 group-hover:scale-110 transition-transform">
                <FileText size={28} />
            </div>
            <h3 className="font-bold text-slate-800 dark:text-white text-xl mb-3">{t.step3Title}</h3>
            <p className="text-slate-500 dark:text-slate-400 leading-relaxed">{t.step3Desc}</p>
        </div>
      </div>
    </div>
  );

  const DashboardView = () => (
    <div className="space-y-8 animate-fadeIn pb-10">
      <div className="flex justify-between items-end">
        <div>
           <h2 className="text-3xl font-extrabold text-slate-800 dark:text-white flex items-center gap-3">
             <LayoutDashboard className="text-emerald-600 dark:text-emerald-400" size={32} />
             {t.dashboardTitle}
           </h2>
           <p className="text-slate-500 dark:text-slate-400 mt-2 text-lg">{t.dashboardSubtitle}</p>
        </div>
      </div>

      {budgetAlerts.length > 0 && (
          <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-900/50 text-red-700 dark:text-red-300 px-6 py-4 rounded-2xl flex items-start gap-4 shadow-sm animate-pulse">
            <div className="bg-red-100 dark:bg-red-900/50 p-2 rounded-lg">
                <AlertTriangle className="shrink-0 text-red-600 dark:text-red-400" size={24} />
            </div>
            <div>
              <p className="font-bold text-lg">{t.budgetAlertTitle}</p>
              <ul className="list-disc list-inside text-sm mt-2 space-y-1 opacity-90">
                {budgetAlerts.map((alert, idx) => (
                    <li key={idx}>{alert}</li>
                ))}
              </ul>
            </div>
          </div>
      )}

      <StatsCards stats={stats} translations={t} />

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-1 space-y-8">
           {/* Budget Status Widget */}
           <div className="h-[400px]">
             <BudgetStatus budgets={settings.budgets} currentSpending={spendingByCategory} translations={t} language={language} />
           </div>

           {/* Export Shortcut Card */}
           <div className="relative bg-slate-900 dark:bg-slate-800 rounded-3xl p-8 text-white shadow-2xl overflow-hidden border border-slate-800 dark:border-slate-700">
                <div className="absolute top-0 left-0 w-32 h-32 bg-emerald-500/20 rounded-full blur-3xl -ml-10 -mt-10"></div>
                <div className="absolute bottom-0 right-0 w-32 h-32 bg-blue-500/20 rounded-full blur-3xl -mr-10 -mb-10"></div>

                <div className="relative z-10">
                    <div className="flex items-center gap-3 mb-4">
                        <div className="bg-white/10 p-2.5 rounded-xl border border-white/10 backdrop-blur-md">
                            <Zap size={24} className="text-yellow-300" />
                        </div>
                        <h3 className="font-bold text-xl">{t.quickActions}</h3>
                    </div>
                    <p className="text-slate-300 text-sm mb-6 leading-relaxed">
                        {t.exportDesc}
                    </p>
                    <div className="grid grid-cols-2 gap-4">
                        <button 
                            onClick={handleExportWord} 
                            disabled={invoices.length === 0} 
                            className="bg-white/10 hover:bg-white/20 border border-white/10 py-3 rounded-xl text-sm font-bold transition-all disabled:opacity-50 flex items-center justify-center gap-2"
                        >
                            <FileText size={16} /> Word
                        </button>
                        <button 
                            onClick={handlePrintPDF} 
                            disabled={invoices.length === 0} 
                            className="bg-emerald-600 hover:bg-emerald-500 py-3 rounded-xl text-sm font-bold transition-all disabled:opacity-50 shadow-lg shadow-emerald-900/20 flex items-center justify-center gap-2"
                        >
                            <FileDown size={16} /> PDF
                        </button>
                    </div>
                </div>
           </div>

           <ExpensesChart data={chartData} translations={t} isDarkMode={isDarkMode} />
        </div>

        <div className="lg:col-span-2 space-y-8">
          <BudgetComparisonChart data={budgetComparisonData} translations={t} isDarkMode={isDarkMode} />
          <RecentInvoices invoices={invoices} translations={t} language={language} />
        </div>
      </div>
    </div>
  );

  const ReportsView = () => (
    <div className="space-y-8 animate-fadeIn max-w-6xl mx-auto">
      <div className="bg-white dark:bg-slate-800 p-10 rounded-[40px] shadow-sm border border-emerald-100 dark:border-slate-700 text-center relative overflow-hidden transition-colors">
        <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-emerald-400 via-blue-500 to-emerald-400"></div>

        <div className="inline-block p-5 bg-emerald-50 dark:bg-emerald-900/30 rounded-3xl mb-6 shadow-sm">
            <ShieldCheck className="w-12 h-12 text-emerald-600 dark:text-emerald-400" />
        </div>
        <h2 className="text-3xl font-extrabold text-slate-800 dark:text-white mb-3">{t.reportsTitle}</h2>
        <p className="text-slate-500 dark:text-slate-400 max-w-2xl mx-auto mb-10 text-lg">
            {t.reportsSubtitle}
        </p>

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 max-w-3xl mx-auto">
            <button 
                onClick={handleExportWord}
                disabled={invoices.length === 0}
                className="group relative flex flex-col items-center p-6 bg-white dark:bg-slate-700 border-2 border-slate-100 dark:border-slate-600 hover:border-blue-500 dark:hover:border-blue-500 rounded-3xl hover:shadow-xl transition-all disabled:opacity-50 disabled:cursor-not-allowed"
            >
                <div className="w-16 h-16 bg-blue-50 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 rounded-2xl flex items-center justify-center mb-4 group-hover:scale-110 transition-transform">
                  <FileText size={32} />
                </div>
                <h3 className="text-xl font-bold text-slate-800 dark:text-white mb-2">{t.reportWord}</h3>
                <p className="text-sm text-slate-500 dark:text-slate-400">{t.reportWordDesc}</p>
            </button>

            <button 
                onClick={handlePrintPDF}
                disabled={invoices.length === 0}
                className="group relative flex flex-col items-center p-6 bg-white dark:bg-slate-700 border-2 border-slate-100 dark:border-slate-600 hover:border-emerald-500 dark:hover:border-emerald-500 rounded-3xl hover:shadow-xl transition-all disabled:opacity-50 disabled:cursor-not-allowed"
            >
                <div className="w-16 h-16 bg-emerald-50 dark:bg-emerald-900/30 text-emerald-600 dark:text-emerald-400 rounded-2xl flex items-center justify-center mb-4 group-hover:scale-110 transition-transform">
                  <FileDown size={32} />
                </div>
                <h3 className="text-xl font-bold text-slate-800 dark:text-white mb-2">{t.reportPdf}</h3>
                <p className="text-sm text-slate-500 dark:text-slate-400">{t.reportPdfDesc}</p>
            </button>
        </div>
      </div>

      <div className="bg-white dark:bg-slate-800 p-8 rounded-3xl shadow-sm border border-slate-100 dark:border-slate-700 transition-colors">
        <h3 className="text-xl font-bold text-slate-800 dark:text-white mb-6 flex items-center gap-2">
            <FileText className="text-slate-400 dark:text-slate-500" size={24} />
            {t.fullHistory}
        </h3>
        <RecentInvoices invoices={invoices} translations={t} language={language} />
      </div>
    </div>
  );

  // If user is not logged in, show Login Screen
  if (!user) {
    return (
      <div className={`min-h-screen bg-slate-50 dark:bg-slate-950 font-sans text-slate-900 dark:text-slate-100 ${language === 'ar' ? 'rtl' : 'ltr'} transition-colors duration-300`} dir={language === 'ar' ? 'rtl' : 'ltr'}>
          {/* Header minimal for Login */}
           <div className="fixed top-0 w-full p-4 flex justify-between items-center z-50">
               <div className="bg-slate-800/50 p-1 rounded-lg border border-white/10 flex items-center backdrop-blur-md">
                    <button 
                        onClick={() => setLanguage('en')}
                        className={`px-2 py-1 rounded-md text-xs font-bold transition-all ${language === 'en' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-400 hover:text-white'}`}
                    >
                        EN
                    </button>
                    <button 
                        onClick={() => setLanguage('ar')}
                        className={`px-2 py-1 rounded-md text-xs font-bold transition-all ${language === 'ar' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-400 hover:text-white'}`}
                    >
                        عربي
                    </button>
               </div>
               <button
                    onClick={() => setTheme(theme === 'dark' ? 'light' : 'dark')}
                    className="p-2 bg-slate-800/50 text-emerald-100 hover:text-white hover:bg-white/10 rounded-lg transition-all border border-white/10 backdrop-blur-md"
                >
                    {isDarkMode ? <Sun size={18} /> : <Moon size={18} />}
                </button>
           </div>
          <LoginScreen onLogin={handleLogin} translations={t} language={language} />
      </div>
    );
  }

  return (
    <div className={`min-h-screen bg-slate-50 dark:bg-slate-950 font-sans text-slate-900 dark:text-slate-100 ${language === 'ar' ? 'rtl' : 'ltr'} transition-colors duration-300`} dir={language === 'ar' ? 'rtl' : 'ltr'}>
      <Header 
        onScanClick={handleScanClick}
        activeView={activeView}
        onNavigate={setActiveView}
        onOpenBudgetSettings={() => setIsSettingsModalOpen(true)}
        language={language}
        onToggleLanguage={setLanguage}
        translations={t}
        theme={theme}
        onToggleTheme={(newTheme) => setTheme(newTheme)}
        user={user}
        onLogout={handleLogout}
        onOpenSubscription={() => setIsSubscriptionModalOpen(true)}
      />

      <main className="container mx-auto px-4 py-8 pb-32">
        {activeView === 'home' && <HomeView />}
        {activeView === 'dashboard' && <DashboardView />}
        {activeView === 'reports' && <ReportsView />}
      </main>

      {isScanning && (
        <ScannerModal 
          onClose={() => setIsScanning(false)}
          onInvoiceAdded={handleInvoiceAdded}
          defaultCurrency={settings.defaultCurrency}
          translations={t}
        />
      )}

      {isSettingsModalOpen && (
        <SettingsModal 
          currentSettings={settings}
          userProfile={user}
          onSave={(newSettings) => setSettings(newSettings)}
          onUpdateProfile={handleUpdateProfile}
          onClose={() => setIsSettingsModalOpen(false)}
          translations={t}
          language={language}
        />
      )}

      {isSubscriptionModalOpen && user && (
          <SubscriptionModal 
            currentSubscription={user.subscription}
            onUpgrade={handleUpgrade}
            onClose={() => setIsSubscriptionModalOpen(false)}
            translations={t}
            language={language}
          />
      )}

      <ChatBot invoices={invoices} translations={t} />
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { X, Save, Calculator, Globe, CreditCard, Building2, UserCircle, FileBadge, Mail } from 'lucide-react';
import { ExpenseCategory, AppSettings, CURRENCIES, CATEGORY_MAPPING, UserProfile } from '../types';

interface SettingsModalProps {
  currentSettings: AppSettings;
  userProfile: UserProfile | null;
  onSave: (settings: AppSettings) => void;
  onUpdateProfile: (profile: UserProfile) => void;
  onClose: () => void;
  translations: any;
  language: string;
}

type Tab = 'general' | 'budgets' | 'profile';

const SettingsModal: React.FC<SettingsModalProps> = ({ 
    currentSettings, 
    userProfile, 
    onSave, 
    onUpdateProfile, 
    onClose, 
    translations: t, 
    language 
}) => {
  const [activeTab, setActiveTab] = useState<Tab>('general');
  const [settings, setSettings] = useState<AppSettings>(currentSettings);

  // Profile State
  const [profile, setProfile] = useState<UserProfile>(userProfile || {
      companyName: '',
      email: '',
      crNumber: '',
      vatNumber: '',
      subscription: {
          plan: 'FREE',
          cycle: 'MONTHLY',
          usageCount: 0,
          limit: 30,
          renewalDate: new Date().toISOString()
      }
  });

  const handleBudgetChange = (category: ExpenseCategory, value: string) => {
    const numValue = parseFloat(value);
    setSettings(prev => ({
      ...prev,
      budgets: {
          ...prev.budgets,
          [category]: isNaN(numValue) ? 0 : numValue
      }
    }));
  };

  const handleCurrencyChange = (code: string) => {
      setSettings(prev => ({
          ...prev,
          defaultCurrency: code
      }));
  };

  const handleSave = () => {
    if (activeTab === 'profile') {
        onUpdateProfile(profile);
    } else {
        onSave(settings);
    }
    onClose();
  };

  const getCategoryLabel = (cat: string) => {
    return language === 'en' && CATEGORY_MAPPING[cat] ? CATEGORY_MAPPING[cat] : cat;
  };

  const isAr = language === 'ar';

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm">
      <div className="bg-white dark:bg-slate-900 rounded-3xl shadow-2xl w-full max-w-lg p-0 relative max-h-[90vh] overflow-hidden flex flex-col transition-colors">
        {/* Header */}
        <div className="p-6 pb-2 border-b border-slate-100 dark:border-slate-800">
            <button 
                onClick={onClose}
                className="absolute left-4 top-4 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 transition-colors"
            >
                <X size={24} />
            </button>
            <h2 className="text-2xl font-bold text-slate-800 dark:text-white text-center">{t.settings.title}</h2>
        </div>

        {/* Tabs */}
        <div className="flex border-b border-slate-100 dark:border-slate-800">
            <button 
                onClick={() => setActiveTab('general')}
                className={`flex-1 py-4 text-sm font-bold flex items-center justify-center gap-2 transition-colors border-b-2 ${activeTab === 'general' ? 'text-emerald-600 dark:text-emerald-400 border-emerald-600 dark:border-emerald-400 bg-emerald-50/50 dark:bg-emerald-900/20' : 'text-slate-500 dark:text-slate-400 border-transparent hover:bg-slate-50 dark:hover:bg-slate-800'}`}
            >
                <Globe size={18} />
                <span className="hidden sm:inline">{t.settings.tabGeneral}</span>
            </button>
            <button 
                onClick={() => setActiveTab('budgets')}
                className={`flex-1 py-4 text-sm font-bold flex items-center justify-center gap-2 transition-colors border-b-2 ${activeTab === 'budgets' ? 'text-blue-600 dark:text-blue-400 border-blue-600 dark:border-blue-400 bg-blue-50/50 dark:bg-blue-900/20' : 'text-slate-500 dark:text-slate-400 border-transparent hover:bg-slate-50 dark:hover:bg-slate-800'}`}
            >
                <Calculator size={18} />
                <span className="hidden sm:inline">{t.settings.tabBudgets}</span>
            </button>
            <button 
                onClick={() => setActiveTab('profile')}
                className={`flex-1 py-4 text-sm font-bold flex items-center justify-center gap-2 transition-colors border-b-2 ${activeTab === 'profile' ? 'text-purple-600 dark:text-purple-400 border-purple-600 dark:border-purple-400 bg-purple-50/50 dark:bg-purple-900/20' : 'text-slate-500 dark:text-slate-400 border-transparent hover:bg-slate-50 dark:hover:bg-slate-800'}`}
            >
                <Building2 size={18} />
                <span className="hidden sm:inline">{isAr ? 'ملف الشركة' : 'Company'}</span>
            </button>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-6">
            {activeTab === 'general' && (
                <div className="space-y-6 animate-fadeIn">
                    <div>
                        <label className="block text-slate-700 dark:text-slate-300 font-bold mb-3 flex items-center gap-2">
                            <CreditCard size={18} className="text-emerald-500" />
                            {t.settings.defaultCurrency}
                        </label>
                        <p className="text-sm text-slate-500 dark:text-slate-400 mb-4">
                            {t.settings.currencyDesc}
                        </p>
                        <div className="grid grid-cols-2 gap-3">
                            {CURRENCIES.map((curr) => (
                                <button
                                    key={curr.code}
                                    onClick={() => handleCurrencyChange(curr.code)}
                                    className={`p-3 rounded-xl border text-right transition-all ${
                                        settings.defaultCurrency === curr.code 
                                        ? 'border-emerald-500 dark:border-emerald-400 bg-emerald-50 dark:bg-emerald-900/30 text-emerald-800 dark:text-emerald-300 ring-1 ring-emerald-500' 
                                        : 'border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-400 hover:border-emerald-200 dark:hover:border-emerald-700'
                                    }`}
                                >
                                    <div className="font-bold flex justify-between">
                                        <span>{language === 'ar' ? curr.nameAr : curr.nameEn}</span>
                                        <span className="font-mono text-sm opacity-50">{curr.code}</span>
                                    </div>
                                    <div className="text-sm opacity-70 mt-1">{curr.symbol}</div>
                                </button>
                            ))}
                        </div>
                    </div>
                </div>
            )}

            {activeTab === 'budgets' && (
                <div className="space-y-4 animate-fadeIn">
                     <p className="text-sm text-slate-500 dark:text-slate-400 mb-2">{t.settings.budgetDesc}</p>
                     {Object.values(ExpenseCategory).map((category) => (
                        <div key={category} className="flex items-center gap-4">
                        <label className="w-1/2 text-sm font-medium text-slate-700 dark:text-slate-300">{getCategoryLabel(category)}</label>
                        <div className="relative w-1/2">
                            <input
                            type="number"
                            min="0"
                            step="10"
                            value={settings.budgets[category] || ''}
                            onChange={(e) => handleBudgetChange(category, e.target.value)}
                            placeholder="0.000"
                            className="w-full px-4 py-2 border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-800 dark:text-white rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none text-left ltr"
                            dir="ltr"
                            />
                            <span className="absolute right-3 top-1/2 -translate-y-1/2 text-xs text-slate-400 font-medium">{t.settings.currencyUnit}</span>
                        </div>
                        </div>
                    ))}
                </div>
            )}

            {activeTab === 'profile' && (
                <div className="space-y-6 animate-fadeIn">
                    <div className="flex items-center gap-4 bg-purple-50 dark:bg-purple-900/20 p-4 rounded-2xl border border-purple-100 dark:border-purple-800">
                        <div className="w-12 h-12 bg-purple-100 dark:bg-purple-900/50 text-purple-600 dark:text-purple-400 rounded-full flex items-center justify-center">
                            <UserCircle size={28} />
                        </div>
                        <div>
                            <h3 className="font-bold text-slate-800 dark:text-white">{profile.companyName || 'اسم الشركة'}</h3>
                            <p className="text-xs text-slate-500 dark:text-slate-400">{profile.email}</p>
                        </div>
                    </div>

                    <div className="space-y-4">
                        <div>
                            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5 flex items-center gap-2">
                                <Building2 size={16} className="text-slate-400" />
                                {t.login.companyName}
                            </label>
                            <input
                                type="text"
                                value={profile.companyName}
                                onChange={(e) => setProfile(prev => ({ ...prev, companyName: e.target.value }))}
                                className="w-full px-4 py-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-purple-500 outline-none transition-all dark:text-white"
                            />
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5 flex items-center gap-2">
                                <Mail size={16} className="text-slate-400" />
                                {t.login.email}
                            </label>
                            <input
                                type="email"
                                value={profile.email}
                                onChange={(e) => setProfile(prev => ({ ...prev, email: e.target.value }))}
                                className="w-full px-4 py-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-purple-500 outline-none transition-all dark:text-white"
                            />
                        </div>

                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5 flex items-center gap-2">
                                    <FileBadge size={16} className="text-slate-400" />
                                    {isAr ? 'رقم السجل' : 'CR No.'}
                                </label>
                                <input
                                    type="text"
                                    value={profile.crNumber}
                                    onChange={(e) => setProfile(prev => ({ ...prev, crNumber: e.target.value }))}
                                    className="w-full px-4 py-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-purple-500 outline-none transition-all dark:text-white"
                                />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5 flex items-center gap-2">
                                    <FileBadge size={16} className="text-slate-400" />
                                    {isAr ? 'الرقم الضريبي' : 'VAT No.'}
                                </label>
                                <input
                                    type="text"
                                    value={profile.vatNumber || ''}
                                    onChange={(e) => setProfile(prev => ({ ...prev, vatNumber: e.target.value }))}
                                    className="w-full px-4 py-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-purple-500 outline-none transition-all dark:text-white"
                                />
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </div>

        {/* Footer */}
        <div className="p-6 pt-0">
            <button 
            onClick={handleSave}
