            rows: [vatReturnHeader, rowStandardBase, rowStandardVat, rowZero, rowExempt],
            spacing: { after: 400 }
        }),

        // Warning Section if any Standard Rated invoice misses Tax ID
        ...(standardRatedInvoices.some(inv => !inv.vendorTaxId) ? [
