                        <button 
                            onClick={handleExportWord} 
                            disabled={invoices.length === 0} 
                            className="bg-white/10 hover:bg-white/20 border border-white/10 py-3 rounded-xl text-sm font-bold transition-all disabled:opacity-50 flex items-center justify-center gap-2"
                        >
                            <FileText size={16} /> Word
                        </button>
                        <button 
                            onClick={handlePrintPDF} 
                            disabled={invoices.length === 0} 
                            className="bg-emerald-600 hover:bg-emerald-500 py-3 rounded-xl text-sm font-bold transition-all disabled:opacity-50 shadow-lg shadow-emerald-900/20 flex items-center justify-center gap-2"
