// Helper to convert file to base64
export const fileToGenerativePart = async (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64String = reader.result as string;
      const base64Data = base64String.split(',')[1];
      resolve(base64Data);
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

// Helper for delay
const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

// Retry Wrapper with Exponential Backoff
async function retryWithBackoff<T>(fn: () => Promise<T>, retries = 5, initialDelay = 3000): Promise<T> {
  let currentDelay = initialDelay;
  for (let i = 0; i < retries; i++) {
    try {
      return await fn();
    } catch (error: any) {
      // Enhanced error checking for 429 / RESOURCE_EXHAUSTED
      const status = error?.status || error?.code || error?.error?.code || error?.response?.status;
      const message = error?.message || error?.error?.message || '';
      const errorString = JSON.stringify(error);

      const isRateLimit = 
        status === 429 || 
        status === 'RESOURCE_EXHAUSTED' ||
        message.includes('429') || 
        message.includes('quota') ||
        message.includes('RESOURCE_EXHAUSTED') ||
        errorString.includes('RESOURCE_EXHAUSTED');

      if (isRateLimit) {
         if (i < retries - 1) {
            console.warn(`API Quota hit (429). Retrying in ${currentDelay}ms... (Attempt ${i + 1}/${retries})`);
            await delay(currentDelay);
            currentDelay *= 2; // Double the delay for next attempt
            continue;
         } else {
             // If we exhausted retries, throw a user-friendly error
             throw new Error("تم تجاوز حد الاستخدام (Quota). يرجى الانتظار قليلاً والمحاولة مرة أخرى.");
         }
      }

      // If it's not a rate limit error, throw immediately
      throw error;
    }
  }
  throw new Error("تعذر معالجة الطلب بسبب ضغط على الخادم.");
}

/**
 * Main Orchestrator - Optimized Single Pass
 * Performs OCR and Accounting Analysis in ONE call to save API Quota.
 */
export const processInvoiceWithGemini = async (base64Image: string, defaultCurrency: string = 'OMR'): Promise<Omit<InvoiceData, 'id'>> => {
  return retryWithBackoff(async () => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const systemInstruction = `
      Identity: You are "Fyniq AI" (فينيك الذكي), an expert Omani Tax Accountant.
      Task: Analyze invoice for Omani VAT Return (Filling) compliance.

      **Process:**
      1. **Vendor Details**: Extract Name, **Phone Number**, and **Tax Registration Number (VATIN/TRN)**. If VATIN is missing, this is critical.
      2. **Financials**: Extract Total, Date, and Currency.
      3. **Currency Conversion**: Convert amounts to **OMR** (approx: 1 USD=0.385, 1 AED=0.105, 1 SAR=0.103, 1 EUR=0.420).
      4. **VAT Analysis (Oman Law)**:
         - **Standard Rated (5%)**: Most goods/services. Formula: VAT = Total - (Total / 1.05).
         - **Zero Rated (0%)**: Basic food, Medicines, Int'l Transport, Oil/Gas.
         - **Exempt**: Residential Rent, Local Transport, Financial Services, Salaries.

      5. **Status Determination ('vatStatus')**:
         - 'مطابق' (Compliant): VAT amount matches ~5% OR it is clearly Zero/Exempt AND Vendor has Tax ID.
         - 'غير مطابق' (Non-Compliant): VAT amount is wrong (> 0.010 diff) OR Vendor charges VAT but has NO Tax ID.
         - 'صفرية' (Zero-rated): Specifically for basic foods/medicines/exports.
         - 'معفى' (Exempt): Specifically for rent/salaries/financial.

      **Output Fields**:
      - vendorName: String
      - vendorPhone: String (Digits found or 'N/A')
      - vendorTaxId: String (Found TRN or 'N/A')
      - date: YYYY-MM-DD
      - totalAmount: Number (OMR)
      - vatAmount: Number (OMR)
      - originalAmount: Number (Original Currency)
      - currency: ISO Code
      - category: One of [${Object.values(ExpenseCategory).join(', ')}]
      - description: Short summary
      - vatStatus: One of ['مطابق', 'غير مطابق', 'معفى', 'صفرية']
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
          { text: "Analyze for Oman VAT Return." }
        ]
      },
      config: {
        systemInstruction: systemInstruction,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            vendorName: { type: Type.STRING },
            vendorPhone: { type: Type.STRING, description: "Vendor Phone Number if present" },
            vendorTaxId: { type: Type.STRING, description: "Vendor VAT/Tax ID if present" },
            date: { type: Type.STRING },
            totalAmount: { type: Type.NUMBER, description: "Total in OMR" },
            vatAmount: { type: Type.NUMBER, description: "VAT in OMR" },
            originalAmount: { type: Type.NUMBER, description: "Total in Original Currency" },
            currency: { type: Type.STRING, description: "ISO Currency Code" },
            category: { type: Type.STRING, enum: Object.values(ExpenseCategory) },
            description: { type: Type.STRING },
            vatStatus: { type: Type.STRING, enum: ['مطابق', 'غير مطابق', 'معفى', 'صفرية'] }
          },
          required: ["vendorName", "date", "totalAmount", "vatAmount", "originalAmount", "currency", "category", "description", "vatStatus"]
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("Empty response from AI");

    return JSON.parse(text);
  });
};

export const generateMarkdownReport = (invoices: InvoiceData[]): string => {
  const date = new Date().toLocaleDateString('ar-OM');

  let md = `# تقرير المصروفات اليومي - ${date}\n`;
  md += `---\n\n`;

  invoices.forEach((inv, index) => {
    md += `### فاتورة رقم ${index + 1}\n`;
    md += `| البيان | التفاصيل |\n`;
    md += `| :--- | :--- |\n`;
    md += `| **اسم المورد** | ${inv.vendorName} |\n`;
    md += `| **رقم الهاتف** | ${inv.vendorPhone || '-'} |\n`;
    md += `| **الرقم الضريبي للمورد** | ${inv.vendorTaxId || 'غير متوفر'} |\n`;
    md += `| **الوصف** | ${inv.description || '-'} |\n`;
    md += `| **التصنيف المحاسبي** | ${inv.category} |\n`;

    if (inv.currency !== 'OMR') {
        md += `| **المبلغ الأصلي** | ${inv.originalAmount.toFixed(2)} ${inv.currency} |\n`;
        md += `| **المبلغ المعادل** | ${inv.totalAmount.toFixed(3)} ر.ع |\n`;
    } else {
        md += `| **المبلغ الإجمالي** | ${inv.totalAmount.toFixed(3)} ر.ع |\n`;
    }

    md += `| **قيمة الضريبة (5%)** | ${inv.vatAmount.toFixed(3)} ر.ع |\n`;
    md += `| **الحالة الضريبية** | ${inv.vatStatus} |\n\n`;

    if (inv.vatStatus === 'غير مطابق') {
        md += `> **ملاحظة المحاسب الذكي:** يرجى مراجعة هذه الفاتورة. قد يكون الرقم الضريبي مفقوداً أو قيمة الضريبة غير صحيحة.\n\n`;
    }
    md += `---\n`;
  });

  return md;
};

