const App: React.FC = () => {
  const [activeView, setActiveView] = useState<ViewState>('home');
  const [isScanning, setIsScanning] = useState(false);
  const [isSettingsModalOpen, setIsSettingsModalOpen] = useState(false);
  const [isSubscriptionModalOpen, setIsSubscriptionModalOpen] = useState(false);

  // User Authentication State
  const [user, setUser] = useState<UserProfile | null>(() => {
     try {
         const savedUser = localStorage.getItem('fyniq_user');
         return savedUser ? JSON.parse(savedUser) : null;
     } catch(e) { return null; }
  });

  // Theme State
  const [theme, setTheme] = useState<Theme>(() => {
    if (typeof window !== 'undefined') {
      const saved = localStorage.getItem('app_theme');
      if (saved) return saved as Theme;
      return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
    }
    return 'light';
  });

  // Language State
  const [language, setLanguage] = useState<Language>(() => {
     return (localStorage.getItem('app_language') as Language) || 'ar';
  });

  // Handle Theme Side Effects
  useEffect(() => {
    localStorage.setItem('app_theme', theme);
    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [theme]);

  // Handle Language Side Effects
  useEffect(() => {
    localStorage.setItem('app_language', language);
    document.documentElement.lang = language;
    document.documentElement.dir = language === 'ar' ? 'rtl' : 'ltr';
  }, [language]);

  const t = TRANSLATIONS[language];
  const isDarkMode = theme === 'dark';

  // Initialize invoices from localStorage
  const [invoices, setInvoices] = useState<InvoiceData[]>(() => {
    try {
      const saved = localStorage.getItem('omani_accountant_invoices');
      return saved ? JSON.parse(saved) : [];
    } catch (e) {
      console.error("Failed to load invoices", e);
      return [];
    }
  });

  // Initialize Settings
  const [settings, setSettings] = useState<AppSettings>(() => {
    try {
      const saved = localStorage.getItem('omani_accountant_settings');
      if (saved) {
          return JSON.parse(saved);
      }
      const legacyBudgets = localStorage.getItem('omani_accountant_budgets');
      return {
          defaultCurrency: 'OMR',
          budgets: legacyBudgets ? JSON.parse(legacyBudgets) : {}
      };
    } catch (e) {
      return { defaultCurrency: 'OMR', budgets: {} };
    }
  });

  // Save invoices when changed
  useEffect(() => {
    localStorage.setItem('omani_accountant_invoices', JSON.stringify(invoices));
  }, [invoices]);

  // Save settings when changed
  useEffect(() => {
    localStorage.setItem('omani_accountant_settings', JSON.stringify(settings));
    localStorage.setItem('omani_accountant_budgets', JSON.stringify(settings.budgets));
  }, [settings]);

  // Handle User Login
  const handleLogin = (profile: Omit<UserProfile, 'subscription'>) => {
      // Initialize Default Subscription for new users
      const profileWithSub: UserProfile = {
          ...profile,
          subscription: {
              plan: 'FREE',
              cycle: 'MONTHLY',
              usageCount: invoices.length, // Sync with existing invoice count logic for now
              limit: 30,
              renewalDate: new Date(new Date().setMonth(new Date().getMonth() + 1)).toISOString()
          }
      };

      setUser(profileWithSub);
      localStorage.setItem('fyniq_user', JSON.stringify(profileWithSub));
      setActiveView('dashboard'); // Auto redirect to dashboard on login
  };

  // Handle Profile Update
  const handleUpdateProfile = (updatedProfile: UserProfile) => {
    setUser(updatedProfile);
    localStorage.setItem('fyniq_user', JSON.stringify(updatedProfile));
  };

  // Handle Plan Upgrade
  const handleUpgrade = (plan: PlanType, cycle: 'MONTHLY' | 'YEARLY') => {
      if (!user) return;

      const limits: Record<PlanType, number> = {
          'FREE': 30,
          'STANDARD': 70,
          'ENTERPRISE': -1
      };

      const updatedUser: UserProfile = {
          ...user,
          subscription: {
              ...user.subscription,
              plan: plan,
              cycle: cycle,
              limit: limits[plan],
              // In real app, reset usage on cycle change or keep it? Keeping for now.
          }
      };
      setUser(updatedUser);
      localStorage.setItem('fyniq_user', JSON.stringify(updatedUser));
      setIsSubscriptionModalOpen(false);
      alert(`Successfully upgraded to ${plan} Plan!`);
  };

  // Handle User Logout
  const handleLogout = () => {
      setUser(null);
      localStorage.removeItem('fyniq_user');
      setActiveView('home');
  };

  // Derived State
  const stats: DashboardStats = useMemo(() => {
    return invoices.reduce((acc, curr) => ({
      totalSpend: acc.totalSpend + curr.totalAmount,
      totalVat: acc.totalVat + curr.vatAmount,
      invoiceCount: acc.invoiceCount + 1
    }), { totalSpend: 0, totalVat: 0, invoiceCount: 0 });
  }, [invoices]);

  const spendingByCategory = useMemo(() => {
    return invoices.reduce((acc, curr) => {
      acc[curr.category] = (acc[curr.category] || 0) + curr.totalAmount;
      return acc;
    }, {} as Record<string, number>);
  }, [invoices]);

  // Helper to get translated category name
  const getCategoryName = (cat: string) => {
      return language === 'en' && CATEGORY_MAPPING[cat] ? CATEGORY_MAPPING[cat] : cat;
  };

  const chartData: ChartData[] = useMemo(() => {
    const colors: Record<string, string> = {
      [ExpenseCategory.COGS]: '#059669',
      [ExpenseCategory.OPERATING]: '#3b82f6',
      [ExpenseCategory.SALARY]: '#8b5cf6',
      [ExpenseCategory.MARKETING]: '#f59e0b',
      [ExpenseCategory.ADMIN]: '#64748b',
      [ExpenseCategory.ASSETS]: '#0ea5e9',
      [ExpenseCategory.UTILITIES]: '#ec4899',
    };

    return Object.entries(spendingByCategory).map(([name, value]) => ({
      name: getCategoryName(name), // Translate name
      value,
      fill: colors[name] || '#cbd5e1'
    }));
  }, [spendingByCategory, language]);

  const budgetComparisonData = useMemo(() => {
    return Object.values(ExpenseCategory).map(cat => ({
      name: getCategoryName(cat), // Translate name
      actual: spendingByCategory[cat] || 0,
      budget: settings.budgets[cat] || 0
    })).filter(item => item.actual > 0 || item.budget > 0);
  }, [spendingByCategory, settings.budgets, language]);

  const budgetAlerts = useMemo(() => {
    const alerts: string[] = [];
    Object.entries(settings.budgets).forEach(([cat, limit]) => {
        if (limit && spendingByCategory[cat] > limit) {
            const catName = getCategoryName(cat);
            const msg = language === 'ar' 
                ? `تنبيه: لقد تجاوزت موازنة "${catName}" المحددة (${limit} ر.ع)`
                : `Alert: You exceeded budget for "${catName}" (${limit} OMR)`;
            alerts.push(msg);
        }
    });
    return alerts;
  }, [settings.budgets, spendingByCategory, language]);

  const handleScanClick = () => {
    if (!user) return;

    // Check Limits
    const limit = user.subscription.limit;
    const current = user.subscription.usageCount;

    if (limit !== -1 && current >= limit) {
        setIsSubscriptionModalOpen(true);
        // Optional: show a specific alert inside modal or before opening
        return;
    }

    setIsScanning(true);
  };

  const handleInvoiceAdded = (newInvoiceData: Omit<InvoiceData, 'id'>) => {
    const newInvoice: InvoiceData = {
      ...newInvoiceData,
      id: crypto.randomUUID(),
    };
    setInvoices(prev => [newInvoice, ...prev]);

    // Increment Usage Logic
    if (user) {
        const updatedUser = {
            ...user,
            subscription: {
                ...user.subscription,
                usageCount: user.subscription.usageCount + 1
            }
        };
        setUser(updatedUser);
        localStorage.setItem('fyniq_user', JSON.stringify(updatedUser));
    }

    setActiveView('dashboard');
  };

  const handleExportWord = () => {
    generateVatReturnReport(invoices);
  };

  const handlePrintPDF = () => {
    window.print();
  };

  // --- Views Components ---

  const HomeView = () => (
    <div className="flex flex-col items-center justify-center py-10 text-center animate-fadeIn">
      {/* Hero Section */}
      <div className="relative w-full max-w-5xl mx-auto bg-gradient-to-b from-white to-slate-50 dark:from-slate-800 dark:to-slate-900 rounded-[40px] p-8 md:p-16 shadow-2xl shadow-slate-200 dark:shadow-slate-900 border border-white dark:border-slate-700 overflow-hidden transition-all">

        {/* Decorative Background Elements */}
        <div className="absolute top-0 right-0 w-96 h-96 bg-emerald-100/50 dark:bg-emerald-500/10 rounded-full blur-3xl -mr-20 -mt-20"></div>
        <div className="absolute bottom-0 left-0 w-96 h-96 bg-blue-100/50 dark:bg-blue-500/10 rounded-full blur-3xl -ml-20 -mb-20"></div>

        <div className="relative z-10">
            <div className="inline-flex items-center gap-2 bg-white/80 dark:bg-slate-800/80 border border-slate-200 dark:border-slate-700 backdrop-blur-sm px-4 py-1.5 rounded-full text-sm font-semibold text-slate-600 dark:text-slate-300 mb-6 shadow-sm">
                <BrainCircuit size={16} className="text-emerald-500" />
                <span>{t.aiBadge}</span>
            </div>

            <h2 className="text-5xl md:text-7xl font-extrabold text-slate-800 dark:text-white mb-6 leading-tight tracking-tight">
                {t.heroTitle}
            </h2>

            <p className="text-xl text-slate-500 dark:text-slate-400 max-w-2xl mx-auto mb-10 leading-relaxed">
                {t.heroSubtitle}
            </p>

            <div className="flex flex-col sm:flex-row justify-center gap-4">
                <button 
                onClick={() => setActiveView('dashboard')}
                className="bg-slate-900 dark:bg-white text-white dark:text-slate-900 px-10 py-4 rounded-2xl font-bold hover:bg-slate-800 dark:hover:bg-slate-200 transition-all shadow-xl shadow-slate-200 dark:shadow-slate-900/50 flex items-center justify-center gap-3 group"
                >
                <span>{t.btnDashboard}</span>
                {language === 'ar' ? <ChevronRight className="group-hover:-translate-x-1 transition-transform" /> : <ChevronRight className="group-hover:translate-x-1 transition-transform" />}
                </button>
                <button 
                onClick={handleScanClick}
                className="bg-emerald-500 text-white border border-emerald-400 px-10 py-4 rounded-2xl font-bold hover:bg-emerald-400 transition-all flex items-center justify-center gap-3 shadow-xl shadow-emerald-200 dark:shadow-emerald-900/50"
                >
                <ScanLine size={22} />
                <span>{t.btnScan}</span>
                </button>
            </div>
        </div>
      </div>

      {/* Feature Grid */}
      <div className={`mt-16 grid grid-cols-1 md:grid-cols-3 gap-6 w-full max-w-5xl ${language === 'ar' ? 'text-right' : 'text-left'}`}>
        <div className="bg-white dark:bg-slate-800 p-8 rounded-3xl shadow-lg border border-slate-100 dark:border-slate-700 hover:border-emerald-200 dark:hover:border-emerald-700 transition-colors group">
            <div className="w-14 h-14 bg-emerald-50 dark:bg-emerald-900/30 text-emerald-600 dark:text-emerald-400 rounded-2xl flex items-center justify-center mb-6 group-hover:scale-110 transition-transform">
                <Camera size={28} />
            </div>
            <h3 className="font-bold text-slate-800 dark:text-white text-xl mb-3">{t.step1Title}</h3>
            <p className="text-slate-500 dark:text-slate-400 leading-relaxed">{t.step1Desc}</p>
        </div>
        <div className="bg-white dark:bg-slate-800 p-8 rounded-3xl shadow-lg border border-slate-100 dark:border-slate-700 hover:border-blue-200 dark:hover:border-blue-700 transition-colors group">
            <div className="w-14 h-14 bg-blue-50 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 rounded-2xl flex items-center justify-center mb-6 group-hover:scale-110 transition-transform">
                <BrainCircuit size={28} />
            </div>
            <h3 className="font-bold text-slate-800 dark:text-white text-xl mb-3">{t.step2Title}</h3>
            <p className="text-slate-500 dark:text-slate-400 leading-relaxed">{t.step2Desc}</p>
        </div>
        <div className="bg-white dark:bg-slate-800 p-8 rounded-3xl shadow-lg border border-slate-100 dark:border-slate-700 hover:border-purple-200 dark:hover:border-purple-700 transition-colors group">
            <div className="w-14 h-14 bg-purple-50 dark:bg-purple-900/30 text-purple-600 dark:text-purple-400 rounded-2xl flex items-center justify-center mb-6 group-hover:scale-110 transition-transform">
                <FileText size={28} />
            </div>
            <h3 className="font-bold text-slate-800 dark:text-white text-xl mb-3">{t.step3Title}</h3>
            <p className="text-slate-500 dark:text-slate-400 leading-relaxed">{t.step3Desc}</p>
        </div>
      </div>
    </div>
  );

  const DashboardView = () => (
    <div className="space-y-8 animate-fadeIn pb-10">
      <div className="flex justify-between items-end">
        <div>
           <h2 className="text-3xl font-extrabold text-slate-800 dark:text-white flex items-center gap-3">
             <LayoutDashboard className="text-emerald-600 dark:text-emerald-400" size={32} />
             {t.dashboardTitle}
           </h2>
           <p className="text-slate-500 dark:text-slate-400 mt-2 text-lg">{t.dashboardSubtitle}</p>
        </div>
      </div>

      {budgetAlerts.length > 0 && (
          <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-900/50 text-red-700 dark:text-red-300 px-6 py-4 rounded-2xl flex items-start gap-4 shadow-sm animate-pulse">
            <div className="bg-red-100 dark:bg-red-900/50 p-2 rounded-lg">
                <AlertTriangle className="shrink-0 text-red-600 dark:text-red-400" size={24} />
            </div>
            <div>
              <p className="font-bold text-lg">{t.budgetAlertTitle}</p>
              <ul className="list-disc list-inside text-sm mt-2 space-y-1 opacity-90">
                {budgetAlerts.map((alert, idx) => (
                    <li key={idx}>{alert}</li>
                ))}
              </ul>
            </div>
          </div>
      )}

      <StatsCards stats={stats} translations={t} />

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-1 space-y-8">
           {/* Budget Status Widget */}
           <div className="h-[400px]">
             <BudgetStatus budgets={settings.budgets} currentSpending={spendingByCategory} translations={t} language={language} />
           </div>

           {/* Export Shortcut Card */}
           <div className="relative bg-slate-900 dark:bg-slate-800 rounded-3xl p-8 text-white shadow-2xl overflow-hidden border border-slate-800 dark:border-slate-700">
                <div className="absolute top-0 left-0 w-32 h-32 bg-emerald-500/20 rounded-full blur-3xl -ml-10 -mt-10"></div>
                <div className="absolute bottom-0 right-0 w-32 h-32 bg-blue-500/20 rounded-full blur-3xl -mr-10 -mb-10"></div>

                <div className="relative z-10">
