            <button 
                onClick={handleExportWord}
                disabled={invoices.length === 0}
                className="group relative flex flex-col items-center p-6 bg-white dark:bg-slate-700 border-2 border-slate-100 dark:border-slate-600 hover:border-blue-500 dark:hover:border-blue-500 rounded-3xl hover:shadow-xl transition-all disabled:opacity-50 disabled:cursor-not-allowed"
            >
                <div className="w-16 h-16 bg-blue-50 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 rounded-2xl flex items-center justify-center mb-4 group-hover:scale-110 transition-transform">
                  <Landmark size={32} />
                </div>
                <h3 className="text-xl font-bold text-slate-800 dark:text-white mb-2">{t.reportTax}</h3>
                <p className="text-sm text-slate-500 dark:text-slate-400">{t.reportTaxDesc}</p>
            </button>

            <button 
                onClick={handlePrintPDF}
                disabled={invoices.length === 0}
                className="group relative flex flex-col items-center p-6 bg-white dark:bg-slate-700 border-2 border-slate-100 dark:border-slate-600 hover:border-emerald-500 dark:hover:border-emerald-500 rounded-3xl hover:shadow-xl transition-all disabled:opacity-50 disabled:cursor-not-allowed"
            >
                <div className="w-16 h-16 bg-emerald-50 dark:bg-emerald-900/30 text-emerald-600 dark:text-emerald-400 rounded-2xl flex items-center justify-center mb-4 group-hover:scale-110 transition-transform">
                  <FileDown size={32} />
                </div>
                <h3 className="text-xl font-bold text-slate-800 dark:text-white mb-2">{t.reportPdf}</h3>
                <p className="text-sm text-slate-500 dark:text-slate-400">{t.reportPdfDesc}</p>
            </button>
        </div>
      </div>

      <div className="bg-white dark:bg-slate-800 p-8 rounded-3xl shadow-sm border border-slate-100 dark:border-slate-700 transition-colors">
        <h3 className="text-xl font-bold text-slate-800 dark:text-white mb-6 flex items-center gap-2">
            <FileText className="text-slate-400 dark:text-slate-500" size={24} />
            {t.fullHistory}
        </h3>
        <RecentInvoices invoices={invoices} translations={t} language={language} />
      </div>
    </div>
  );

  // If user is not logged in, show Login Screen
  if (!user) {
    return (
      <div className={`min-h-screen bg-slate-50 dark:bg-slate-950 font-sans text-slate-900 dark:text-slate-100 ${language === 'ar' ? 'rtl' : 'ltr'} transition-colors duration-300`} dir={language === 'ar' ? 'rtl' : 'ltr'}>
          {/* Header minimal for Login */}
           <div className="fixed top-0 w-full p-4 flex justify-between items-center z-50">
               <div className="bg-slate-800/50 p-1 rounded-lg border border-white/10 flex items-center backdrop-blur-md">
                    <button 
                        onClick={() => setLanguage('en')}
                        className={`px-2 py-1 rounded-md text-xs font-bold transition-all ${language === 'en' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-400 hover:text-white'}`}
                    >
                        EN
                    </button>
                    <button 
                        onClick={() => setLanguage('ar')}
                        className={`px-2 py-1 rounded-md text-xs font-bold transition-all ${language === 'ar' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-400 hover:text-white'}`}
                    >
                        عربي
                    </button>
               </div>
               <button
                    onClick={() => setTheme(theme === 'dark' ? 'light' : 'dark')}
                    className="p-2 bg-slate-800/50 text-emerald-100 hover:text-white hover:bg-white/10 rounded-lg transition-all border border-white/10 backdrop-blur-md"
                >
                    {isDarkMode ? <Sun size={18} /> : <Moon size={18} />}
                </button>
           </div>
          <LoginScreen onLogin={handleLogin} translations={t} language={language} />
      </div>
    );
  }

  return (
    <div className={`min-h-screen bg-slate-50 dark:bg-slate-950 font-sans text-slate-900 dark:text-slate-100 ${language === 'ar' ? 'rtl' : 'ltr'} transition-colors duration-300`} dir={language === 'ar' ? 'rtl' : 'ltr'}>
      <Header 
        onScanClick={handleScanClick}
        activeView={activeView}
        onNavigate={setActiveView}
        onOpenBudgetSettings={() => setIsSettingsModalOpen(true)}
        language={language}
        onToggleLanguage={setLanguage}
        translations={t}
        theme={theme}
        onToggleTheme={(newTheme) => setTheme(newTheme)}
        user={user}
        onLogout={handleLogout}
        onOpenSubscription={() => setIsSubscriptionModalOpen(true)}
      />

      <main className="container mx-auto px-4 py-8 pb-32">
        {activeView === 'home' && <HomeView />}
        {activeView === 'dashboard' && <DashboardView />}
        {activeView === 'reports' && <ReportsView />}
      </main>

      {isScanning && (
        <ScannerModal 
          onClose={() => setIsScanning(false)}
          onInvoiceAdded={handleInvoiceAdded}
          defaultCurrency={settings.defaultCurrency}
          translations={t}
        />
      )}

      {isSettingsModalOpen && (
        <SettingsModal 
          currentSettings={settings}
          userProfile={user}
          onSave={(newSettings) => setSettings(newSettings)}
          onUpdateProfile={handleUpdateProfile}
          onClose={() => setIsSettingsModalOpen(false)}
          translations={t}
          language={language}
        />
      )}

      {isSubscriptionModalOpen && user && (
          <SubscriptionModal 
            currentSubscription={user.subscription}
            onUpgrade={handleUpgrade}
            onClose={() => setIsSubscriptionModalOpen(false)}
            translations={t}
            language={language}
          />
      )}

      <ChatBot invoices={invoices} translations={t} />
    </div>
  );
};

