    isDarkMode: boolean;
}

// Pricing constants matching the app logic (SubscriptionModal)
const PRICING = {
    FREE: { MONTHLY: 0, YEARLY: 0 },
    STANDARD: { MONTHLY: 4, YEARLY: 40 },
    ENTERPRISE: { MONTHLY: 50, YEARLY: 500 } // Estimated base for Enterprise
