import React, { useState, useRef } from 'react';
import { X, Upload, Camera, Loader2, AlertCircle, Receipt, CreditCard } from 'lucide-react';
import { fileToGenerativePart, processInvoiceWithGemini } from '../services/geminiService';
import { InvoiceData } from '../types';

interface ScannerModalProps {
  onClose: () => void;
  onInvoiceAdded: (invoice: Omit<InvoiceData, 'id'>) => void;
  defaultCurrency: string;
  translations: any;
}

const ScannerModal: React.FC<ScannerModalProps> = ({ onClose, onInvoiceAdded, defaultCurrency, translations: t }) => {
  const [isProcessing, setIsProcessing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    await processFile(file);
  };

  const processFile = async (file: File) => {
    setIsProcessing(true);
    setError(null);
    try {
        const base64Data = await fileToGenerativePart(file);
        // Pass the default currency to the AI service
        const data = await processInvoiceWithGemini(base64Data, defaultCurrency);
        onInvoiceAdded(data);
        onClose();
    } catch (e: any) {
        console.error(e);
        setError(t.scanner.error);
    } finally {
        setIsProcessing(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-emerald-900/40 backdrop-blur-sm">
      <div className="bg-white dark:bg-slate-900 rounded-3xl shadow-2xl w-full max-w-lg p-6 relative transition-colors">
        <button 
          onClick={onClose}
          className="absolute left-4 top-4 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 transition-colors"
        >
          <X size={24} />
        </button>

        <div className="text-center mt-4 mb-8">
          <div className="inline-flex items-center justify-center w-16 h-16 bg-emerald-100 dark:bg-emerald-900/30 text-emerald-600 dark:text-emerald-400 rounded-full mb-4">
            <Camera size={32} />
          </div>
          <h2 className="text-2xl font-bold text-slate-800 dark:text-white">{t.scanner.title}</h2>
          <p className="text-slate-500 dark:text-slate-400 text-sm mt-1">{t.scanner.subtitle}</p>
        </div>

        {error && (
            <div className="mb-6 p-4 bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 rounded-xl text-sm flex items-center gap-2">
                <AlertCircle size={16} className="shrink-0" />
                {error}
            </div>
        )}

        {isProcessing ? (
          <div className="flex flex-col items-center justify-center py-12 space-y-4">
            <Loader2 className="animate-spin text-emerald-600 dark:text-emerald-400 w-12 h-12" />
            <p className="text-emerald-800 dark:text-emerald-300 font-medium animate-pulse">{t.scanner.processing}</p>
            <p className="text-xs text-slate-400">{t.scanner.processingDesc}</p>
          </div>
        ) : (
          <div className="space-y-4">
            <input 
                type="file" 
                accept="image/*" 
                capture="environment"
                className="hidden" 
                ref={fileInputRef}
                onChange={handleFileChange}
            />

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <button 
                    onClick={() => fileInputRef.current?.click()}
                    className="flex flex-col items-center gap-4 p-6 border-2 border-dashed border-slate-200 dark:border-slate-700 rounded-2xl bg-white dark:bg-slate-800 hover:bg-emerald-50 dark:hover:bg-emerald-900/10 hover:border-emerald-300 dark:hover:border-emerald-700 transition-all group"
                >
                    <div className="p-3 bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 rounded-xl group-hover:scale-110 transition-transform">
                        <Receipt size={28} />
                    </div>
                    <div className="text-center">
                        <span className="block font-bold text-slate-800 dark:text-white text-sm">{t.scanner.scanTax}</span>
                        <span className="text-[10px] text-slate-400">فواتير ضريبية، سجل المشتريات</span>
                    </div>
                </button>

                <button 
                    onClick={() => fileInputRef.current?.click()}
                    className="flex flex-col items-center gap-4 p-6 border-2 border-dashed border-slate-200 dark:border-slate-700 rounded-2xl bg-white dark:bg-slate-800 hover:bg-purple-50 dark:hover:bg-purple-900/10 hover:border-purple-300 dark:hover:border-purple-700 transition-all group"
                >
                    <div className="p-3 bg-purple-100 dark:bg-purple-900/30 text-purple-600 dark:text-purple-400 rounded-xl group-hover:scale-110 transition-transform">
                        <CreditCard size={28} />
                    </div>
                    <div className="text-center">
                        <span className="block font-bold text-slate-800 dark:text-white text-sm">{t.scanner.scanVisa}</span>
                        <span className="text-[10px] text-slate-400">إيصالات نقاط البيع، تتبع البطاقة</span>
                    </div>
                </button>
            </div>

            <button 
                onClick={() => fileInputRef.current?.click()}
                className="w-full py-3 bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-400 rounded-xl text-xs font-medium hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors flex items-center justify-center gap-2"
            >
                <Upload size={14} />
                <span>أو ارفع ملف موجود مسبقاً</span>
            </button>

            <p className="text-xs text-center text-slate-400 dark:text-slate-500 pt-2">
                {t.scanner.supportText.replace('{curr}', defaultCurrency)}
