                                    <CreditCard size={12} /> آخر 4 أرقام من البطاقة
                                </label>
                                <input 
                                    type="text" 
                                    value={reviewData.cardLast4 || ''}
                                    onChange={(e) => updateReviewField('cardLast4', e.target.value)}
