import React, { useState, useRef } from 'react';
import { X, Upload, Camera, Loader2, AlertCircle, Receipt, CreditCard, Save, Edit3, Calendar, Building2, DollarSign, Tag, CheckCircle2, BrainCircuit } from 'lucide-react';
import { fileToGenerativePart, processInvoiceWithGemini } from '../services/geminiService';
import { InvoiceData, ExpenseCategory, CURRENCIES, AccountType } from '../types';

interface ScannerModalProps {
  onClose: () => void;
  onInvoiceAdded: (invoice: Omit<InvoiceData, 'id'>) => void;
  defaultCurrency: string;
  translations: any;
  accountType?: AccountType;
}

const ScannerModal: React.FC<ScannerModalProps> = ({ onClose, onInvoiceAdded, defaultCurrency, translations: t, accountType }) => {
  const [isProcessing, setIsProcessing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [reviewData, setReviewData] = useState<Omit<InvoiceData, 'id'> | null>(null);
  const [capturedImage, setCapturedImage] = useState<string | null>(null);

  // Ref for Direct Camera Capture
  const fileInputRef = useRef<HTMLInputElement>(null);
  // Ref for Gallery/File Selection
  const galleryInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    await processFile(file);
  };

  const processFile = async (file: File) => {
    setIsProcessing(true);
    setError(null);
    try {
        const fileData = await fileToGenerativePart(file);
        // Create accessible URL for the image to store in history
        const imageUrl = `data:${fileData.mimeType};base64,${fileData.data}`;
        setCapturedImage(imageUrl);

        // Now passing the object { data, mimeType } directly
        const data = await processInvoiceWithGemini(fileData, defaultCurrency);
        setReviewData(data);
    } catch (e: any) {
        console.error(e);
        setError(t.scanner.error);
    } finally {
        setIsProcessing(false);
    }
  };

  const handleConfirmSave = () => {
    if (reviewData) {
        onInvoiceAdded({
            ...reviewData,
            imageUrl: capturedImage || undefined
        });
        onClose();
    }
  };

  const updateReviewField = (field: keyof Omit<InvoiceData, 'id'>, value: any) => {
    if (reviewData) {
        setReviewData({ ...reviewData, [field]: value });
    }
  };

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
      <div className="bg-white dark:bg-slate-900 rounded-[32px] shadow-2xl w-full max-w-xl relative transition-colors overflow-hidden flex flex-col max-h-[90vh]">

        {/* Header */}
        <div className="p-6 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center bg-white dark:bg-slate-900 sticky top-0 z-10">
          <div>
            <h2 className="text-xl font-bold text-slate-800 dark:text-white">
                {reviewData ? "مراجعة وتدقيق البيانات" : t.scanner.title}
            </h2>
            {!reviewData && <p className="text-slate-500 dark:text-slate-400 text-xs mt-1">{t.scanner.subtitle}</p>}
          </div>
          <button 
            onClick={onClose}
            className="p-2 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 transition-colors bg-slate-100 dark:bg-slate-800 rounded-full"
          >
            <X size={20} />
          </button>
        </div>

        <div className="overflow-y-auto flex-1 p-6">
            {error && (
                <div className="mb-6 p-4 bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 rounded-2xl text-sm flex items-center gap-2 border border-red-100 dark:border-red-800">
                    <AlertCircle size={18} className="shrink-0" />
                    {error}
                </div>
            )}

            {isProcessing ? (
              <div className="flex flex-col items-center justify-center py-20 space-y-6">
                <div className="relative">
                    <Loader2 className="animate-spin text-emerald-600 dark:text-emerald-400 w-16 h-16" strokeWidth={1.5} />
                    <BrainCircuit className="absolute inset-0 m-auto text-emerald-500 w-6 h-6 animate-pulse" />
                </div>
                <div className="text-center">
                    <p className="text-xl font-bold text-slate-800 dark:text-white mb-2">{t.scanner.processing}</p>
                    <p className="text-sm text-slate-400">{t.scanner.processingDesc}</p>
                </div>
              </div>
            ) : reviewData ? (
              /* Review Form */
              <div className="space-y-5 animate-fadeIn">
                <div className="bg-emerald-50 dark:bg-emerald-900/10 p-4 rounded-2xl border border-emerald-100 dark:border-emerald-800 flex items-center gap-3 mb-2">
                    <CheckCircle2 className="text-emerald-500" size={24} />
                    <p className="text-sm text-emerald-800 dark:text-emerald-300 font-medium">تم استخراج البيانات بنجاح. يرجى التأكد من صحتها قبل الحفظ.</p>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {/* Image Preview (Small) */}
                    {capturedImage && (
                        <div className="md:col-span-2 flex justify-center mb-2">
                            <img src={capturedImage} alt="Scanned Invoice" className="h-40 rounded-xl border border-slate-200 dark:border-slate-700 object-contain bg-slate-100 dark:bg-slate-800" />
                        </div>
                    )}

                    {/* Merchant Name */}
                    <div className="md:col-span-2">
                        <label className="text-xs font-bold text-slate-500 dark:text-slate-400 mb-1.5 flex items-center gap-1">
                            <Building2 size={12} /> اسم المورد / المحل
                        </label>
                        <input 
                            type="text" 
                            value={reviewData.vendorName}
                            onChange={(e) => updateReviewField('vendorName', e.target.value)}
                            className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl outline-none focus:ring-2 focus:ring-emerald-500 dark:text-white font-bold"
                        />
                    </div>

                    {/* Date */}
                    <div>
                        <label className="text-xs font-bold text-slate-500 dark:text-slate-400 mb-1.5 flex items-center gap-1">
                            <Calendar size={12} /> التاريخ
                        </label>
                        <input 
                            type="text" 
                            value={reviewData.date}
                            onChange={(e) => updateReviewField('date', e.target.value)}
                            className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl outline-none focus:ring-2 focus:ring-emerald-500 dark:text-white"
                        />
                    </div>

                    {/* Category */}
                    <div>
                        <label className="text-xs font-bold text-slate-500 dark:text-slate-400 mb-1.5 flex items-center gap-1">
                            <Tag size={12} /> التصنيف المحاسبي
                        </label>
                        <select 
                            value={reviewData.category}
                            onChange={(e) => updateReviewField('category', e.target.value)}
                            className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl outline-none focus:ring-2 focus:ring-emerald-500 dark:text-white"
                        >
                            {Object.values(ExpenseCategory).map(cat => (
                                <option key={cat} value={cat}>{cat}</option>
                            ))}
                        </select>
                    </div>

                    {/* Total Amount */}
                    <div>
                        <label className="text-xs font-bold text-slate-500 dark:text-slate-400 mb-1.5 flex items-center gap-1">
                            <DollarSign size={12} /> المبلغ الإجمالي (ر.ع)
                        </label>
                        <input 
                            type="number" 
                            step="0.001"
                            value={reviewData.totalAmount}
                            onChange={(e) => updateReviewField('totalAmount', parseFloat(e.target.value))}
                            className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl outline-none focus:ring-2 focus:ring-emerald-500 dark:text-white font-mono font-bold"
                        />
                    </div>

                    {/* VAT Amount */}
                    <div>
                        <label className="text-xs font-bold text-slate-500 dark:text-slate-400 mb-1.5 flex items-center gap-1">
                            <Receipt size={12} /> ضريبة القيمة المضافة
                        </label>
                        <input 
                            type="number" 
                            step="0.001"
                            value={reviewData.vatAmount}
                            onChange={(e) => updateReviewField('vatAmount', parseFloat(e.target.value))}
                            className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl outline-none focus:ring-2 focus:ring-emerald-500 dark:text-white font-mono"
                        />
                    </div>

                    {/* Payment Method Details (If CARD) */}
                    {reviewData.paymentMethod === 'CARD' && (
                        <>
                            <div>
                                <label className="text-xs font-bold text-slate-500 dark:text-slate-400 mb-1.5 flex items-center gap-1">
                                    <CreditCard size={12} /> آخر 4 أرقام من البطاقة
                                </label>
                                <input 
                                    type="text" 
                                    value={reviewData.cardLast4 || ''}
                                    onChange={(e) => updateReviewField('cardLast4', e.target.value)}
                                    placeholder="مثلاً: 3970"
                                    className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl outline-none focus:ring-2 focus:ring-emerald-500 dark:text-white font-mono"
                                />
                            </div>
                            <div>
                                <label className="text-xs font-bold text-slate-500 dark:text-slate-400 mb-1.5 flex items-center gap-1">
                                    <Edit3 size={12} /> رمز الموافقة (Auth Code)
                                </label>
                                <input 
                                    type="text" 
                                    value={reviewData.authCode || ''}
                                    onChange={(e) => updateReviewField('authCode', e.target.value)}
                                    placeholder="037839"
                                    className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl outline-none focus:ring-2 focus:ring-emerald-500 dark:text-white font-mono"
                                />
                            </div>
                        </>
                    )}
                </div>
              </div>
            ) : (
              /* Upload Options */
              <div className="space-y-4 animate-fadeIn">
                {/* Input for Camera (Force Environment) */}
                <input 
                    type="file" 
                    accept="image/*" 
                    capture="environment"
                    className="hidden" 
                    ref={fileInputRef}
                    onChange={handleFileChange}
                />

                {/* Input for Gallery/Files (No capture attribute) */}
                <input 
                    type="file" 
                    accept="image/*" 
                    className="hidden" 
                    ref={galleryInputRef}
                    onChange={handleFileChange}
                />

                <div className={`grid grid-cols-1 ${accountType === 'INDIVIDUAL' ? '' : 'sm:grid-cols-2'} gap-4`}>
                    {accountType !== 'INDIVIDUAL' && (
                        <button 
                            onClick={() => {
                                if (fileInputRef.current) fileInputRef.current.value = '';
                                fileInputRef.current?.click();
                            }}
                            className="flex flex-col items-center gap-4 p-8 border-2 border-dashed border-slate-200 dark:border-slate-700 rounded-3xl bg-white dark:bg-slate-800 hover:bg-emerald-50 dark:hover:bg-emerald-900/10 hover:border-emerald-300 dark:hover:border-emerald-700 transition-all group"
                        >
                            <div className="p-4 bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 rounded-2xl group-hover:scale-110 transition-transform">
                                <Receipt size={32} />
                            </div>
                            <div className="text-center">
                                <span className="block font-bold text-slate-800 dark:text-white text-base">{t.scanner.scanTax}</span>
                                <span className="text-xs text-slate-400 mt-1">فواتير ضريبية، سجل المشتريات</span>
                            </div>
                        </button>
                    )}

                    <button 
                        onClick={() => {
                            if (fileInputRef.current) fileInputRef.current.value = '';
                            fileInputRef.current?.click();
                        }}
                        className={`flex flex-col items-center gap-4 p-8 border-2 border-dashed border-slate-200 dark:border-slate-700 rounded-3xl bg-white dark:bg-slate-800 hover:bg-purple-50 dark:hover:bg-purple-900/10 hover:border-purple-300 dark:hover:border-purple-700 transition-all group ${accountType === 'INDIVIDUAL' ? 'w-full' : ''}`}
                    >
                        <div className="p-4 bg-purple-100 dark:bg-purple-900/30 text-purple-600 dark:text-purple-400 rounded-2xl group-hover:scale-110 transition-transform">
                            <CreditCard size={32} />
                        </div>
                        <div className="text-center">
                            <span className="block font-bold text-slate-800 dark:text-white text-base">{t.scanner.scanVisa}</span>
                            <span className="text-xs text-slate-400 mt-1">إيصالات نقاط البيع، تتبع البطاقة</span>
                        </div>
                    </button>
                </div>

                <button 
                    onClick={() => {
                        if (galleryInputRef.current) galleryInputRef.current.value = '';
                        galleryInputRef.current?.click();
                    }}
                    className="w-full py-4 bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 rounded-2xl text-sm font-bold hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors flex items-center justify-center gap-2 border border-slate-200 dark:border-slate-700"
                >
                    <Upload size={18} />
                    <span>أو ارفع ملف من جهازك</span>
                </button>

                <p className="text-xs text-center text-slate-400 dark:text-slate-500 pt-2">
                    {t.scanner.supportText.replace('{curr}', defaultCurrency)}
                </p>
              </div>
            )}
        </div>

        {/* Footer Actions */}
        {reviewData && !isProcessing && (
            <div className="p-6 border-t border-slate-100 dark:border-slate-800 bg-slate-50 dark:bg-slate-900/50">
                <div className="flex gap-3">
                    <button 
                        onClick={() => setReviewData(null)}
                        className="flex-1 py-4 bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 rounded-2xl font-bold hover:bg-slate-200 dark:hover:bg-slate-700 transition-all"
                    >
                        إلغاء
                    </button>
                    <button 
                        onClick={handleConfirmSave}
                        className="flex-[2] py-4 bg-emerald-600 hover:bg-emerald-700 text-white rounded-2xl font-bold shadow-xl shadow-emerald-200 dark:shadow-emerald-900/20 transition-all flex items-center justify-center gap-2"
                    >
                        <Save size={20} />
                        <span>تأكيد وحفظ الفاتورة</span>
                    </button>
                </div>
            </div>
        )}
      </div>
    </div>
  );
};

export default ScannerModal;

import React, { useState } from 'react';
import { InvoiceData } from '../types';
import { Search, Image as ImageIcon, Calendar, FileText, Download, X, ZoomIn } from 'lucide-react';

interface ImageArchiveProps {
  invoices: InvoiceData[];
  translations: any;
  language: string;
}

const ImageArchive: React.FC<ImageArchiveProps> = ({ invoices, translations: t, language }) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedImage, setSelectedImage] = useState<InvoiceData | null>(null);

  // Filter only invoices that have an image
  const invoicesWithImages = invoices.filter(inv => 
    inv.imageUrl && 
    (inv.vendorName.toLowerCase().includes(searchQuery.toLowerCase()) || 
     inv.date.includes(searchQuery))
  );

  return (
    <div className="space-y-6 animate-fadeIn">
      {/* Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800 dark:text-white flex items-center gap-2">
            <ImageIcon className="text-purple-500" size={24} />
            {t.archive.title}
          </h2>
          <p className="text-slate-500 dark:text-slate-400 text-sm mt-1">{t.archive.subtitle}</p>
        </div>

        {/* Search */}
        <div className="relative w-full md:w-72">
            <Search className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
                type="text" 
                placeholder={t.archive.searchPlaceholder}
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full pr-10 pl-4 py-2.5 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-purple-500 outline-none text-sm dark:text-white transition-all shadow-sm"
            />
        </div>
      </div>

      {/* Grid */}
      {invoicesWithImages.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-20 bg-white dark:bg-slate-800 rounded-3xl border border-slate-100 dark:border-slate-700">
            <div className="p-6 bg-slate-50 dark:bg-slate-700/50 rounded-full mb-4">
                <ImageIcon size={40} className="text-slate-300 dark:text-slate-500" />
            </div>
            <p className="text-slate-500 dark:text-slate-400 font-medium">{t.archive.noImages}</p>
        </div>
      ) : (
        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
            {invoicesWithImages.map((invoice) => (
                <div 
                    key={invoice.id} 
                    className="group relative aspect-square bg-white dark:bg-slate-800 rounded-2xl overflow-hidden shadow-sm border border-slate-100 dark:border-slate-700 cursor-pointer hover:shadow-lg transition-all"
                    onClick={() => setSelectedImage(invoice)}
                >
                    <img 
                        src={invoice.imageUrl} 
                        alt={invoice.vendorName} 
                        className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-110"
                    />

                    {/* Overlay Info */}
                    <div className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-black/80 via-black/40 to-transparent p-4 pt-12 translate-y-2 group-hover:translate-y-0 transition-transform">
                        <p className="text-white font-bold text-sm truncate">{invoice.vendorName}</p>
                        <div className="flex justify-between items-end mt-1">
                            <span className="text-white/80 text-xs flex items-center gap-1">
                                <Calendar size={10} /> {invoice.date}
                            </span>
                            <span className="text-emerald-300 text-xs font-mono font-bold" dir="ltr">
                                {invoice.totalAmount.toFixed(3)}
                            </span>
                        </div>
                    </div>

                    <div className="absolute top-2 left-2 p-2 bg-black/30 backdrop-blur-md rounded-full text-white opacity-0 group-hover:opacity-100 transition-opacity">
                        <ZoomIn size={16} />
                    </div>
                </div>
            ))}
        </div>
      )}

      {/* Modal Viewer */}
      {selectedImage && (
        <div className="fixed inset-0 z-[80] bg-black/90 backdrop-blur-sm flex items-center justify-center p-4" onClick={() => setSelectedImage(null)}>
            <div className="relative w-full max-w-4xl max-h-[90vh] flex flex-col" onClick={e => e.stopPropagation()}>
                <button 
                    onClick={() => setSelectedImage(null)}
                    className="absolute -top-12 left-0 text-white hover:text-slate-300 transition-colors flex items-center gap-2"
                >
                    <X size={24} />
                    <span className="text-sm font-bold">إغلاق</span>
                </button>

                <div className="bg-black rounded-3xl overflow-hidden flex items-center justify-center border border-white/10 shadow-2xl">
                    <img 
                        src={selectedImage.imageUrl} 
                        alt={selectedImage.vendorName} 
                        className="max-w-full max-h-[80vh] object-contain"
                    />
                </div>

                <div className="mt-4 flex justify-between items-center text-white">
                    <div>
                        <h3 className="font-bold text-xl">{selectedImage.vendorName}</h3>
                        <p className="text-sm text-slate-400 flex items-center gap-2">
                            <FileText size={14} /> {selectedImage.description || 'فاتورة'} • {selectedImage.date}
                        </p>
                    </div>
                    <a 
                        href={selectedImage.imageUrl} 
                        download={`invoice-${selectedImage.date}-${selectedImage.vendorName}.jpg`}
                        className="flex items-center gap-2 bg-white text-black px-6 py-3 rounded-xl font-bold hover:bg-slate-200 transition-colors"
                        onClick={(e) => e.stopPropagation()}
                    >
                        <Download size={18} />
                        <span>تحميل</span>
                    </a>
                </div>
            </div>
        </div>
      )}
    </div>
  );
};

export default ImageArchive;

import React from 'react';
import { Wallet, Camera, LayoutDashboard, Home, FileText, Settings, Sparkles, Languages, Moon, Sun, LogOut, User, Crown, CreditCard, Images } from 'lucide-react';
import { Language, Theme, UserProfile } from '../types';

interface HeaderProps {
  onScanClick: () => void;
  activeView: 'home' | 'dashboard' | 'reports' | 'payments' | 'archive';
  onNavigate: (view: 'home' | 'dashboard' | 'reports' | 'payments' | 'archive') => void;
  onOpenBudgetSettings: () => void;
  language: Language;
  onToggleLanguage: (lang: Language) => void;
  translations: any;
  theme: Theme;
  onToggleTheme: (theme: Theme) => void;
  user: UserProfile | null;
  onLogout: () => void;
  onOpenSubscription: () => void;
}

const Header: React.FC<HeaderProps> = ({ 
  onScanClick, 
  activeView, 
  onNavigate, 
  onOpenBudgetSettings,
  language,
  onToggleLanguage,
  translations: t,
  theme,
  onToggleTheme,
  user,
  onLogout,
  onOpenSubscription
}) => {

  // Helper for Desktop Links
  const getLinkClass = (view: string) => {
    const baseClass = "flex items-center gap-2 px-4 py-2 rounded-xl transition-all duration-300 font-medium";
    return activeView === view 
      ? `${baseClass} bg-white/10 text-white shadow-inner backdrop-blur-sm border border-white/10` 
      : `${baseClass} text-emerald-100 hover:bg-white/5 hover:text-white`;
  };

  // Helper for Mobile Bottom Nav Links
  const getMobileLinkClass = (view: string) => {
    const isActive = activeView === view;
    return `flex flex-col items-center justify-center w-full h-full gap-1 ${
      isActive ? 'text-emerald-500 dark:text-emerald-400' : 'text-slate-400 dark:text-slate-500'
    }`;
  };

  const isAr = language === 'ar';
  const isDark = theme === 'dark';

  // Reports are only for Business accounts (or legacy accounts where accountType is undefined)
  const showReports = user?.accountType !== 'INDIVIDUAL';

  // Calculate usage percentage for progress bar
  const usageCount = user?.subscription?.usageCount || 0;
  const usageLimit = user?.subscription?.limit || 1;
  const isUnlimited = usageLimit === -1;
  const usagePercent = isUnlimited ? 0 : Math.min((usageCount / usageLimit) * 100, 100);

  return (
    <>
      {/* Top Header (Desktop & Mobile Minimal) */}
      <header className="bg-gradient-to-r from-slate-900 to-emerald-900 text-white shadow-xl sticky top-0 z-50 border-b border-white/10 transition-colors">
        <div className="container mx-auto px-4 py-3 flex justify-between items-center">
          {/* Logo Section */}
          <div 
            className="flex items-center gap-3 cursor-pointer group" 
            onClick={() => onNavigate('home')}
          >
            <div className="relative">
              <div className="absolute inset-0 bg-emerald-500 blur-lg opacity-40 group-hover:opacity-60 transition-opacity rounded-full"></div>
              <div className="relative p-2.5 bg-gradient-to-br from-white/10 to-white/5 border border-white/10 rounded-xl backdrop-blur-md">
                <Wallet className="w-7 h-7 text-emerald-300" />
                <Sparkles size={12} className="absolute -top-1 -right-1 text-yellow-400 animate-pulse" />
              </div>
            </div>
            <div className="block">
              <h1 className="text-xl font-bold leading-tight tracking-wide">
                {t.header.appName}
              </h1>
              <p className="hidden sm:flex text-[10px] text-emerald-300 tracking-wider font-light items-center gap-1">
                {t.header.poweredBy} <Sparkles size={8} />
              </p>
            </div>
          </div>

          {/* Navigation - Desktop Only */}
          <nav className="hidden md:flex gap-2 text-sm">
            <button onClick={() => onNavigate('home')} className={getLinkClass('home')}>
              <Home size={18} />
              {t.header.home}
            </button>
            <button onClick={() => onNavigate('dashboard')} className={getLinkClass('dashboard')}>
              <LayoutDashboard size={18} />
              {t.header.dashboard}
            </button>
            <button onClick={() => onNavigate('payments')} className={getLinkClass('payments')}>
              <CreditCard size={18} />
              {t.header.payments}
            </button>
            <button onClick={() => onNavigate('archive')} className={getLinkClass('archive')}>
              <Images size={18} />
              {t.header.archive}
            </button>
            {showReports && (
              <button onClick={() => onNavigate('reports')} className={getLinkClass('reports')}>
                <FileText size={18} />
                {t.header.reports}
              </button>
            )}
          </nav>

          {/* Actions */}
          <div className="flex items-center gap-2 md:gap-3">

             {/* Subscription Status */}
             {user && (
               <button 
                 onClick={onOpenSubscription}
                 className="flex items-center gap-3 bg-white/5 hover:bg-white/10 border border-white/10 px-2 md:px-3 py-1.5 rounded-lg transition-all group"
               >
                  <div className={`p-1.5 rounded-md ${user.subscription.plan === 'FREE' ? 'bg-slate-600' : 'bg-amber-500 text-white'}`}>
                      <Crown size={14} fill={user.subscription.plan !== 'FREE' ? "currentColor" : "none"} />
                  </div>
                  {/* Hide detailed stats on mobile, show only icon */}
                  <div className="hidden lg:block text-start">
                      <div className="text-[10px] text-slate-300 leading-tight">
                          {isUnlimited ? 'Unlimited' : `${usageCount}/${usageLimit}`}
                      </div>
                      {!isUnlimited && (
                          <div className="w-16 h-1 bg-white/20 rounded-full mt-0.5 overflow-hidden">
                              <div 
                                  className={`h-full rounded-full ${usagePercent > 90 ? 'bg-red-500' : 'bg-emerald-400'}`} 
                                  style={{ width: `${usagePercent}%` }}
                              ></div>
                          </div>
                      )}
                  </div>
               </button>
             )}

             {/* Theme Toggle */}
             <button
               onClick={() => onToggleTheme(isDark ? 'light' : 'dark')}
               className="p-2 text-emerald-100 hover:text-white hover:bg-white/10 rounded-lg transition-all border border-white/10"
             >
               {isDark ? <Sun size={18} /> : <Moon size={18} />}
             </button>

             {/* Language Switcher */}
             <div className="bg-slate-800/50 p-1 rounded-lg border border-white/10 flex items-center hidden sm:flex">
                <button 
                  onClick={() => onToggleLanguage('en')}
                  className={`px-2 py-1 rounded-md text-xs font-bold transition-all ${!isAr ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-400 hover:text-white'}`}
                >
                  EN
                </button>
                <button 
                  onClick={() => onToggleLanguage('ar')}
                  className={`px-2 py-1 rounded-md text-xs font-bold transition-all ${isAr ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-400 hover:text-white'}`}
                >
                  عربي
                </button>
             </div>

             {/* Mobile Language Toggle (Simple) */}
             <button 
                onClick={() => onToggleLanguage(isAr ? 'en' : 'ar')}
                className="sm:hidden p-2 text-emerald-100 font-bold text-xs border border-white/10 rounded-lg"
             >
                {isAr ? 'EN' : 'عربي'}
             </button>

            <button
              onClick={onOpenBudgetSettings}
              className="p-2.5 text-emerald-100 hover:text-white hover:bg-white/10 rounded-full transition-all border border-transparent hover:border-white/10"
              title={t.header.settings}
            >
              <Settings size={20} />
            </button>

            {/* Logout Button */}
            {user && (
              <button
                  onClick={onLogout}
