import React, { useState } from 'react';
import { BrainCircuit, Building2, Lock, Mail, ArrowRight, Loader2, Wallet, CheckCircle2, AlertCircle, User, ArrowLeft, Eye, EyeOff } from 'lucide-react';
import { UserProfile, Language, AccountType } from '../types';
