                        <label className="text-xs font-bold text-slate-500 dark:text-slate-400 mb-1.5 flex items-center gap-1">
                            <Tag size={12} /> التصنيف المحاسبي
                        </label>
                        <select 
                            value={reviewData.category}
                            onChange={(e) => updateReviewField('category', e.target.value)}
                            className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl outline-none focus:ring-2 focus:ring-emerald-500 dark:text-white"
                        >
                            {Object.values(ExpenseCategory).map(cat => (
                                <option key={cat} value={cat}>{cat}</option>
                            ))}
                        </select>
                    </div>

                    {/* Currency & Original Amount Section */}
                    <div>
                        <label className="text-xs font-bold text-slate-500 dark:text-slate-400 mb-1.5 flex items-center gap-1">
                            <Coins size={12} /> العملة الأصلية
                        </label>
                        <div className="flex gap-2">
                             <select 
                                value={reviewData.currency || 'OMR'}
                                onChange={(e) => handleCurrencyChange(e.target.value)}
                                className="w-1/3 px-2 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl outline-none focus:ring-2 focus:ring-emerald-500 dark:text-white text-sm font-bold"
                            >
                                {CURRENCIES.map(c => (
                                    <option key={c.code} value={c.code}>{c.code}</option>
                                ))}
                            </select>
                            <input 
                                type="number" 
                                step="0.01"
                                value={reviewData.originalAmount || reviewData.totalAmount}
                                onChange={(e) => handleOriginalAmountChange(parseFloat(e.target.value))}
                                className="w-2/3 px-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl outline-none focus:ring-2 focus:ring-emerald-500 dark:text-white font-mono font-bold"
                            />
                        </div>
                    </div>

                    {/* Total Amount (OMR) */}
                    <div>
                        <label className="text-xs font-bold text-slate-500 dark:text-slate-400 mb-1.5 flex items-center gap-1">
                            <DollarSign size={12} /> المعادل بالريال (ر.ع)
                        </label>
                        <div className="relative">
                            <input 
                                type="number" 
                                step="0.001"
                                value={reviewData.totalAmount}
                                onChange={(e) => updateReviewField('totalAmount', parseFloat(e.target.value))}
                                className="w-full px-4 py-3 bg-emerald-50/50 dark:bg-emerald-900/10 border border-emerald-200 dark:border-emerald-800 rounded-xl outline-none focus:ring-2 focus:ring-emerald-500 dark:text-white font-mono font-black text-emerald-800 dark:text-emerald-400"
                            />
                            {(reviewData.currency && reviewData.currency !== 'OMR') && (
                                <div className="absolute top-1/2 -translate-y-1/2 left-3 text-[10px] text-emerald-600 bg-emerald-100 dark:bg-emerald-900 px-1.5 py-0.5 rounded">
                                    <ArrowRightLeft size={10} className="inline mr-1" />
                                    {(reviewData.totalAmount / (reviewData.originalAmount || 1)).toFixed(3)} rate
                                </div>
                            )}
                        </div>
                    </div>

                    {/* VAT Amount */}
                    <div className="md:col-span-2">
                        <label className="text-xs font-bold text-slate-500 dark:text-slate-400 mb-1.5 flex items-center gap-1">
                            <Receipt size={12} /> ضريبة القيمة المضافة (ر.ع)
                        </label>
                        <input 
                            type="number" 
                            step="0.001"
                            value={reviewData.vatAmount}
                            onChange={(e) => updateReviewField('vatAmount', parseFloat(e.target.value))}
                            className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl outline-none focus:ring-2 focus:ring-emerald-500 dark:text-white font-mono"
                        />
                    </div>

                    {/* Payment Method Details (If CARD) */}
                    {reviewData.paymentMethod === 'CARD' && (
                        <>
                            <div>
                                <label className="text-xs font-bold text-slate-500 dark:text-slate-400 mb-1.5 flex items-center gap-1">
                                    <CreditCard size={12} /> آخر 4 أرقام من البطاقة
                                </label>
                                <input 
                                    type="text" 
                                    value={reviewData.cardLast4 || ''}
                                    onChange={(e) => updateReviewField('cardLast4', e.target.value)}
                                    placeholder="مثلاً: 3970"
                                    className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl outline-none focus:ring-2 focus:ring-emerald-500 dark:text-white font-mono"
                                />
                            </div>
                            <div>
                                <label className="text-xs font-bold text-slate-500 dark:text-slate-400 mb-1.5 flex items-center gap-1">
                                    <Edit3 size={12} /> رمز الموافقة (Auth Code)
                                </label>
                                <input 
                                    type="text" 
                                    value={reviewData.authCode || ''}
                                    onChange={(e) => updateReviewField('authCode', e.target.value)}
                                    placeholder="037839"
                                    className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl outline-none focus:ring-2 focus:ring-emerald-500 dark:text-white font-mono"
                                />
                            </div>
                        </>
                    )}
                </div>
              </div>
            ) : (
              /* Upload Options */
              <div className="space-y-4 animate-fadeIn">
                {/* Input for Camera (Force Environment) */}
                <input 
                    type="file" 
                    accept="image/*" 
                    capture="environment"
                    className="hidden" 
                    ref={fileInputRef}
                    onChange={handleFileChange}
                />

                {/* Input for Gallery/Files (No capture attribute) */}
                <input 
                    type="file" 
                    accept="image/*" 
                    className="hidden" 
                    ref={galleryInputRef}
                    onChange={handleFileChange}
                />

                <div className={`grid grid-cols-1 ${accountType === 'INDIVIDUAL' ? '' : 'sm:grid-cols-2'} gap-4`}>
                    {accountType !== 'INDIVIDUAL' && (
                        <button 
                            onClick={() => {
                                if (fileInputRef.current) fileInputRef.current.value = '';
                                fileInputRef.current?.click();
                            }}
                            className="flex flex-col items-center gap-4 p-8 border-2 border-dashed border-slate-200 dark:border-slate-700 rounded-3xl bg-white dark:bg-slate-800 hover:bg-emerald-50 dark:hover:bg-emerald-900/10 hover:border-emerald-300 dark:hover:border-emerald-700 transition-all group"
                        >
                            <div className="p-4 bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 rounded-2xl group-hover:scale-110 transition-transform">
                                <Receipt size={32} />
                            </div>
                            <div className="text-center">
                                <span className="block font-bold text-slate-800 dark:text-white text-base">{t.scanner.scanTax}</span>
                                <span className="text-xs text-slate-400 mt-1">فواتير ضريبية، سجل المشتريات</span>
                            </div>
                        </button>
                    )}

                    <button 
                        onClick={() => {
                            if (fileInputRef.current) fileInputRef.current.value = '';
                            fileInputRef.current?.click();
                        }}
                        className={`flex flex-col items-center gap-4 p-8 border-2 border-dashed border-slate-200 dark:border-slate-700 rounded-3xl bg-white dark:bg-slate-800 hover:bg-purple-50 dark:hover:bg-purple-900/10 hover:border-purple-300 dark:hover:border-purple-700 transition-all group ${accountType === 'INDIVIDUAL' ? 'w-full' : ''}`}
                    >
                        <div className="p-4 bg-purple-100 dark:bg-purple-900/30 text-purple-600 dark:text-purple-400 rounded-2xl group-hover:scale-110 transition-transform">
                            <CreditCard size={32} />
                        </div>
                        <div className="text-center">
                            <span className="block font-bold text-slate-800 dark:text-white text-base">{t.scanner.scanVisa}</span>
                            <span className="text-xs text-slate-400 mt-1">إيصالات نقاط البيع، تتبع البطاقة</span>
                        </div>
                    </button>
                </div>

                <button 
                    onClick={() => {
                        if (galleryInputRef.current) galleryInputRef.current.value = '';
                        galleryInputRef.current?.click();
                    }}
                    className="w-full py-4 bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 rounded-2xl text-sm font-bold hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors flex items-center justify-center gap-2 border border-slate-200 dark:border-slate-700"
                >
                    <Upload size={18} />
                    <span>أو ارفع ملف من جهازك</span>
                </button>

                <p className="text-xs text-center text-slate-400 dark:text-slate-500 pt-2">
                    {t.scanner.supportText.replace('{curr}', defaultCurrency)}
                </p>
              </div>
            )}
        </div>

        {/* Footer Actions */}
        {reviewData && !isProcessing && (
            <div className="p-6 border-t border-slate-100 dark:border-slate-800 bg-slate-50 dark:bg-slate-900/50">
                <div className="flex gap-3">
                    <button 
                        onClick={() => setReviewData(null)}
                        className="flex-1 py-4 bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 rounded-2xl font-bold hover:bg-slate-200 dark:hover:bg-slate-700 transition-all"
                    >
                        إلغاء
                    </button>
                    <button 
                        onClick={handleConfirmSave}
                        className={`flex-[2] py-4 rounded-2xl font-bold shadow-xl transition-all flex items-center justify-center gap-2 text-white ${
                            isPotentialDuplicate 
                            ? 'bg-amber-600 hover:bg-amber-700 shadow-amber-200 dark:shadow-amber-900/20' 
                            : 'bg-emerald-600 hover:bg-emerald-700 shadow-emerald-200 dark:shadow-emerald-900/20'
                        }`}
                    >
                        {isPotentialDuplicate ? <AlertTriangle size={20} /> : <Save size={20} />}
                        <span>{isPotentialDuplicate ? (accountType === 'INDIVIDUAL' ? "تأكيد التكرار" : "تأكيد وحفظ رغم التكرار") : "تأكيد وحفظ الفاتورة"}</span>
                    </button>
                </div>
            </div>
        )}
      </div>
    </div>
  );
};

export default ScannerModal;

import React, { useState } from 'react';
import { InvoiceData, CATEGORY_MAPPING } from '../types';
import { AlertCircle, CheckCircle, Clock, FileText, Calendar, DollarSign, Tag, Coins, Phone, CreditCard, Banknote, ArrowRightLeft } from 'lucide-react';

interface RecentInvoicesProps {
  invoices: InvoiceData[];
  translations: any;
  language: string;
}

const RecentInvoices: React.FC<RecentInvoicesProps> = ({ invoices, translations: t, language }) => {

  const getStatusLabel = (status: string) => {
    if (status === 'مطابق') return t.invoices.statusCorrect;
    if (status === 'غير مطابق') return t.invoices.statusMismatch;
    if (status === 'معفى') return t.invoices.statusExempt;
    return status;
  };

  const getCategoryLabel = (cat: string) => {
    return language === 'en' && CATEGORY_MAPPING[cat] ? CATEGORY_MAPPING[cat] : cat;
  };

  return (
    <div className="bg-white dark:bg-slate-800 rounded-3xl shadow-sm border border-slate-100 dark:border-slate-700 overflow-hidden flex flex-col h-full transition-colors">
      <div className="p-6 border-b border-slate-50 dark:border-slate-700 flex justify-between items-center bg-white dark:bg-slate-800 transition-colors">
        <div className="flex items-center gap-3">
            <div className="p-2 bg-slate-100 dark:bg-slate-700 rounded-lg text-slate-600 dark:text-slate-300">
                <Clock size={20} />
            </div>
            <h2 className="text-xl font-bold text-slate-800 dark:text-white">{t.invoices.title}</h2>
        </div>
        <span className="bg-gradient-to-r from-emerald-50 to-teal-50 dark:from-emerald-900/20 dark:to-teal-900/20 text-emerald-700 dark:text-emerald-400 border border-emerald-100 dark:border-emerald-800 px-3 py-1 rounded-full text-xs font-bold flex items-center gap-1">
          <CheckCircle size={12} />
          {t.invoices.processedBy}
        </span>
      </div>

      <div className="overflow-x-auto flex-1">
        <table className={`w-full text-sm ${language === 'ar' ? 'text-right' : 'text-left'}`}>
          <thead className="bg-slate-50/80 dark:bg-slate-700/50 text-slate-500 dark:text-slate-400 backdrop-blur-sm sticky top-0 z-10">
            <tr>
              <th className="px-6 py-4 font-bold flex items-center gap-2"><Calendar size={14} /> {t.invoices.date}</th>
              <th className="px-6 py-4 font-bold"><div className="flex items-center gap-2"><FileText size={14} /> {t.invoices.vendor}</div></th>
              <th className="px-6 py-4 font-bold"><div className="flex items-center gap-2">وسيلة الدفع</div></th>
              <th className="px-6 py-4 font-bold"><div className="flex items-center gap-2"><Tag size={14} /> {t.invoices.category}</div></th>
              <th className="px-6 py-4 font-bold"><div className="flex items-center gap-2"><Coins size={14} /> {t.invoices.original}</div></th>
              <th className="px-6 py-4 font-bold"><div className="flex items-center gap-2"><DollarSign size={14} /> {t.invoices.equivalent}</div></th>
              <th className="px-6 py-4 font-bold">{t.invoices.status}</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-50 dark:divide-slate-700">
            {invoices.length === 0 ? (
                <tr>
                    <td colSpan={7} className="px-6 py-16 text-center text-slate-400 dark:text-slate-500 bg-slate-50/30 dark:bg-slate-800/30">
                        <div className="flex flex-col items-center gap-3">
                            <div className="p-4 bg-slate-100 dark:bg-slate-700 rounded-full text-slate-300 dark:text-slate-500">
                                <FileText size={32} />
                            </div>
                            <p>{t.invoices.emptyTitle}</p>
                            <p className="text-xs opacity-70">{t.invoices.emptyDesc}</p>
                        </div>
                    </td>
                </tr>
            ) : (
                invoices.map((invoice) => {
                  const isForeign = invoice.currency && invoice.currency !== 'OMR';
                  const rate = isForeign && invoice.originalAmount ? (invoice.totalAmount / invoice.originalAmount).toFixed(3) : null;

                  return (
                    <tr key={invoice.id} className="hover:bg-slate-50 dark:hover:bg-slate-700/50 transition-colors group">
                        <td className="px-6 py-4 text-slate-600 dark:text-slate-300 font-medium whitespace-nowrap">{invoice.date}</td>
                        <td className="px-6 py-4">
                            <div className="font-bold text-slate-800 dark:text-white">{invoice.vendorName}</div>
                            {invoice.vendorPhone && (
                                <div className="text-xs text-slate-500 dark:text-slate-400 flex items-center gap-1 mt-0.5">
                                    <Phone size={10} />
                                    <span dir="ltr">{invoice.vendorPhone}</span>
                                </div>
                            )}
                        </td>
                        <td className="px-6 py-4">
                            {invoice.paymentMethod === 'CARD' ? (
                                <div className="flex items-center gap-2 text-blue-600 dark:text-blue-400">
                                    <CreditCard size={16} />
                                    <span className="font-mono text-xs">**** {invoice.cardLast4 || 'Card'}</span>
                                </div>
                            ) : (
                                <div className="flex items-center gap-2 text-slate-500">
                                    <Banknote size={16} />
                                    <span className="text-xs">نقدي</span>
                                </div>
                            )}
                        </td>
                        <td className="px-6 py-4">
                            <span className="inline-flex items-center px-3 py-1 rounded-full text-xs font-medium bg-blue-50 dark:bg-blue-900/30 text-blue-700 dark:text-blue-300 border border-blue-100 dark:border-blue-800">
                                {getCategoryLabel(invoice.category)}
                            </span>
                        </td>
                        <td className="px-6 py-4 font-medium" dir="ltr">
                            {isForeign ? (
                              <div className="flex flex-col items-end">
                                <span className="text-slate-800 dark:text-slate-200 font-bold">{invoice.originalAmount?.toFixed(2)}</span>
                                <span className="text-slate-400 dark:text-slate-500 text-[10px]">{invoice.currency}</span>
                              </div>
                            ) : (
                              <span className="text-slate-400 dark:text-slate-600">-</span>
                            )}
                        </td>
                        <td className="px-6 py-4" dir="ltr">
                             <div className="flex flex-col items-end">
                                <span className="text-emerald-700 dark:text-emerald-400 font-black font-mono text-base">{invoice.totalAmount.toFixed(3)}</span>
                                {rate && (
                                  <div className="flex items-center gap-1 text-[10px] text-slate-400 bg-slate-100 dark:bg-slate-700/50 px-1.5 py-0.5 rounded">
                                    <ArrowRightLeft size={8} />
                                    <span>{rate}</span>
                                  </div>
                                )}
                             </div>
                        </td>
                        <td className="px-6 py-4">
                            {invoice.vatStatus === 'مطابق' ? (
                                <div className="flex items-center text-emerald-600 dark:text-emerald-400 bg-emerald-50 dark:bg-emerald-900/20 w-fit px-2 py-1 rounded-lg text-xs font-bold gap-1 border border-emerald-100 dark:border-emerald-800">
                                    <CheckCircle size={12} />
                                    <span>{getStatusLabel(invoice.vatStatus)}</span>
                                </div>
                            ) : (
                                <div className="flex items-center text-amber-600 dark:text-amber-400 bg-amber-50 dark:bg-amber-900/20 w-fit px-2 py-1 rounded-lg text-xs font-bold gap-1 border border-amber-100 dark:border-amber-800">
                                    <AlertCircle size={12} />
                                    <span>{getStatusLabel(invoice.vatStatus)}</span>
                                </div>
                            )}
                        </td>
                    </tr>
                  );
                })
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default RecentInvoices;

