interface SettingsModalProps {
  currentSettings: AppSettings;
  userProfile: UserProfile | null;
  onSave: (settings: AppSettings) => void;
  onUpdateProfile: (profile: UserProfile) => void;
  onClose: () => void;
  translations: any;
  language: string;
}

type Tab = 'general' | 'budgets' | 'profile';

const SettingsModal: React.FC<SettingsModalProps> = ({ 
    currentSettings, 
    userProfile, 
    onSave, 
    onUpdateProfile, 
    onClose, 
    translations: t, 
    language 
}) => {
  const [activeTab, setActiveTab] = useState<Tab>('general');
  const [settings, setSettings] = useState<AppSettings>(currentSettings);

  // Custom Budget State
  const [newCustomCategory, setNewCustomCategory] = useState('');
  const [newCustomBudget, setNewCustomBudget] = useState('');

  // Profile State
  const [profile, setProfile] = useState<UserProfile>(userProfile || {
      id: '',
      role: 'USER',
      accountType: 'BUSINESS', // Default fallback
      status: 'ACTIVE',
      companyName: '',
      email: '',
      crNumber: '',
      vatNumber: '',
      subscription: {
          plan: 'FREE',
          cycle: 'MONTHLY',
          usageCount: 0,
          limit: 30,
          renewalDate: new Date().toISOString()
      }
  });

  const handleBudgetChange = (category: string, value: string) => {
    const numValue = parseFloat(value);
    setSettings(prev => ({
      ...prev,
      budgets: {
          ...prev.budgets,
          [category]: isNaN(numValue) ? 0 : numValue
      }
    }));
  };

  const handleAddCustomBudget = () => {
    if (newCustomCategory.trim() && newCustomBudget) {
        handleBudgetChange(newCustomCategory.trim(), newCustomBudget);
        setNewCustomCategory('');
        setNewCustomBudget('');
    }
  };

  const handleDeleteBudget = (category: string) => {
      const newBudgets = { ...settings.budgets };
      delete newBudgets[category];
      setSettings(prev => ({
          ...prev,
          budgets: newBudgets
      }));
  };

  const handleCurrencyChange = (code: string) => {
      setSettings(prev => ({
          ...prev,
          defaultCurrency: code
      }));
  };

  const handleSave = () => {
    if (activeTab === 'profile') {
        onUpdateProfile(profile);
    } else {
        onSave(settings);
    }
    onClose();
