import React from 'react';
import { ExpenseCategory, BudgetLimits, CATEGORY_MAPPING } from '../types';
import { AlertTriangle, CheckCircle, TrendingDown, BellRing, Home, ShoppingBasket, Car, Heart, Landmark, Coffee, ShoppingBag, PiggyBank, Briefcase, Zap, DollarSign, Users } from 'lucide-react';

interface BudgetStatusProps {
  budgets: BudgetLimits;
  currentSpending: Record<string, number>;
  translations: any;
  language: string;
}

const BudgetStatus: React.FC<BudgetStatusProps> = ({ budgets, currentSpending, translations: t, language }) => {
  // Filter categories that actually have a budget set
  const activeBudgets = Object.entries(budgets)
    .filter(([_, limit]) => typeof limit === 'number' && limit > 0) as [string, number][];

  if (activeBudgets.length === 0) {
    return (
      <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700 h-full flex flex-col items-center justify-center text-center transition-colors">
        <div className="p-3 bg-slate-100 dark:bg-slate-700 rounded-full mb-3 text-slate-400 dark:text-slate-500">
            <AlertTriangle size={24} />
        </div>
        <h3 className="text-slate-600 dark:text-slate-300 font-bold mb-1">{t.budgetStatus.noBudgetTitle}</h3>
        <p className="text-xs text-slate-400 dark:text-slate-500">{t.budgetStatus.noBudgetDesc}</p>
      </div>
    );
  }

  const getCategoryLabel = (cat: string) => {
    return language === 'en' && CATEGORY_MAPPING[cat] ? CATEGORY_MAPPING[cat] : cat;
  };

  const getCategoryIcon = (cat: string) => {
      switch(cat) {
          // Individual
          case ExpenseCategory.HOUSING: return <Home size={16} className="text-blue-500" />;
          case ExpenseCategory.GROCERIES: return <ShoppingBasket size={16} className="text-emerald-500" />;
          case ExpenseCategory.TRANSPORT: return <Car size={16} className="text-amber-500" />;
          case ExpenseCategory.HEALTH: return <Heart size={16} className="text-rose-500" />;
          case ExpenseCategory.DEBT: return <Landmark size={16} className="text-indigo-500" />;
          case ExpenseCategory.ENTERTAINMENT: return <Coffee size={16} className="text-pink-500" />;
          case ExpenseCategory.SHOPPING: return <ShoppingBag size={16} className="text-purple-500" />;
          case ExpenseCategory.SAVINGS: return <PiggyBank size={16} className="text-green-600" />;

          // Business
          case ExpenseCategory.COGS: return <Briefcase size={16} className="text-teal-600" />;
          case ExpenseCategory.UTILITIES: return <Zap size={16} className="text-yellow-500" />;
          case ExpenseCategory.SALARY: return <Users size={16} className="text-blue-600" />;
          case ExpenseCategory.OPERATING: return <DollarSign size={16} className="text-cyan-500" />;

          default: return <DollarSign size={16} className="text-slate-400" />;
      }
  };

  return (
    <div className="bg-white dark:bg-slate-800 p-6 rounded-3xl shadow-sm border border-slate-100 dark:border-slate-700 h-full overflow-y-auto transition-colors">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-xl font-bold text-slate-800 dark:text-white flex items-center gap-2">
          <BellRing size={20} className="text-emerald-500" />
          <span>{t.budgetStatus.title}</span>
        </h2>
        <span className="text-[10px] font-bold text-slate-400 dark:text-slate-500 bg-slate-100 dark:bg-slate-700 px-3 py-1 rounded-full uppercase tracking-widest">{t.budgetStatus.monthly}</span>
      </div>

      <div className="space-y-5">
        {activeBudgets.map(([cat, limit]) => {
          const category = cat as ExpenseCategory;
          const spent = currentSpending[category] || 0;
          const percentage = Math.min((spent / limit) * 100, 100);
          const isOverBudget = spent > limit;

          return (
            <div 
              key={category} 
              className={`p-3 rounded-2xl transition-all border ${
                isOverBudget 
                  ? 'bg-rose-50 dark:bg-rose-900/10 border-rose-200 dark:border-rose-800 animate-shake animate-pulse-red' 
                  : 'bg-transparent border-transparent'
              }`}
            >
              <div className="flex justify-between items-end mb-2">
                <div className="flex flex-col">
                  <span className={`text-sm font-bold flex items-center gap-2 ${isOverBudget ? 'text-rose-700 dark:text-rose-400' : 'text-slate-700 dark:text-slate-300'}`}>
                    {getCategoryIcon(category)}
                    {getCategoryLabel(category)}
                  </span>
                  {isOverBudget && (
                    <span className="text-[10px] font-bold text-rose-500 flex items-center gap-1 mt-1">
                      <TrendingDown size={10} />
                      تجاوز بنسبة {Math.round((spent/limit)*100 - 100)}%
                    </span>
                  )}
                </div>
                <div className="text-xs font-mono" dir="ltr">
                  <span className={isOverBudget ? "text-rose-600 dark:text-rose-400 font-black" : "text-slate-600 dark:text-slate-400 font-bold"}>
                    {spent.toFixed(3)}
                  </span>
                  <span className="text-slate-400 dark:text-slate-500"> / {limit.toFixed(1)} {t.stats.currency}</span>
                </div>
              </div>

              <div className="relative h-2.5 w-full bg-slate-100 dark:bg-slate-700 rounded-full overflow-hidden shadow-inner">
                <div 
                  className={`absolute top-0 right-0 h-full rounded-full transition-all duration-700 ease-out ${
                    isOverBudget 
                      ? 'bg-gradient-to-l from-rose-500 to-red-600' 
                      : percentage > 85 
                        ? 'bg-gradient-to-l from-amber-400 to-orange-500' 
                        : 'bg-gradient-to-l from-emerald-400 to-teal-500'
                  }`}
                  style={{ width: `${percentage}%` }}
                />
              </div>

              {isOverBudget && (
                <div className="mt-2 flex items-center gap-2 text-[10px] text-rose-600 dark:text-rose-400 font-black bg-rose-100 dark:bg-rose-900/30 p-1.5 rounded-lg border border-rose-200 dark:border-rose-800">
                  <AlertTriangle size={14} className="animate-bounce" />
                  <span>{t.budgetStatus.overBudget}</span>
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default BudgetStatus;

import React, { useState } from 'react';
import { BrainCircuit, Building2, Lock, Mail, ArrowRight, Loader2, Wallet, CheckCircle2, AlertCircle, User, ArrowLeft, Eye, EyeOff, Languages } from 'lucide-react';
import { UserProfile, Language, AccountType } from '../types';
import { loginUser, registerUser } from '../services/authService';

interface LoginScreenProps {
  onLogin: (profile: UserProfile) => void;
  translations: any;
  language: Language;
  onToggleLanguage: (lang: Language) => void;
}

type AuthView = 'SELECTION' | 'LOGIN' | 'REGISTER';

const LoginScreen: React.FC<LoginScreenProps> = ({ onLogin, translations: t, language, onToggleLanguage }) => {
  const [view, setView] = useState<AuthView>('SELECTION');
  const [accountType, setAccountType] = useState<AccountType | null>(null);

  // Form States
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState(''); // New field for Company Name or Full Name
  const [showPassword, setShowPassword] = useState(false);

  // Validation States
  const [emailError, setEmailError] = useState('');
  const [passwordError, setPasswordError] = useState('');

  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const isAr = language === 'ar';

  const validateEmail = (val: string) => {
    setEmail(val);
    const regex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!val) setEmailError(isAr ? 'البريد الإلكتروني مطلوب' : 'Email is required');
    else if (!regex.test(val)) setEmailError(isAr ? 'بريد إلكتروني غير صالح' : 'Invalid email format');
    else setEmailError('');
  };

  const validatePassword = (val: string) => {
    setPassword(val);
    if (!val) {
        setPasswordError(isAr ? 'كلمة المرور مطلوبة' : 'Password is required');
        return;
    }

    const errors = [];
    if (val.length < 8) errors.push(isAr ? '8 أحرف على الأقل' : 'min 8 chars');
    if (!/[A-Z]/.test(val)) errors.push(isAr ? 'حرف كبير' : 'uppercase');
    if (!/[0-9]/.test(val)) errors.push(isAr ? 'رقم' : 'number');
    if (!/[!@#$%^&*]/.test(val)) errors.push(isAr ? 'رمز خاص' : 'special char');

    if (errors.length > 0) {
        setPasswordError(`${isAr ? 'يجب أن تحتوي على:' : 'Must include:'} ${errors.join(', ')}`);
    } else {
        setPasswordError('');
    }
  };

  const handleSelection = (type: AccountType) => {
      setAccountType(type);
      setView('LOGIN'); // Start with Login, user can switch to Register
  };

  const handleBack = () => {
      if (view === 'LOGIN' || view === 'REGISTER') {
          setView('SELECTION');
          setAccountType(null);
          setError(null);
          setName('');
          setEmail('');
          setPassword('');
      }
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (emailError || passwordError) return;

    setIsLoading(true);
    setError(null);

    try {
        const result = await loginUser(email, password);

        if (result.success && result.user) {
            onLogin(result.user);
        } else {
            setError(result.message || (isAr ? 'فشل تسجيل الدخول' : 'Login failed'));
        }
    } catch (err) {
        setError(isAr ? 'حدث خطأ غير متوقع' : 'Unexpected error');
    } finally {
        setIsLoading(false);
    }
  };

  const handleRegister = async (e: React.FormEvent) => {
    e.preventDefault();
    if (emailError || passwordError || !email || !password || !name) return;

    setIsLoading(true);
    setError(null);

    try {
        const result = await registerUser({
            email, 
            password, 
            accountType: accountType || 'BUSINESS',
            companyName: name // Pass the specific name
        });

        if (result.success && result.user) {
            // Auto login after registration
            onLogin(result.user);
        } else {
            setError(result.message || (isAr ? 'فشل إنشاء الحساب' : 'Registration failed'));
        }
    } catch (err) {
        setError(isAr ? 'حدث خطأ أثناء التسجيل' : 'Registration error');
    } finally {
        setIsLoading(false);
    }
  };

  const handleSocialLogin = (provider: string) => {
      setIsLoading(true);
      setTimeout(() => {
          setIsLoading(false);
          alert(isAr ? `جاري الاتصال بـ ${provider}...` : `Connecting to ${provider}...`);
      }, 1000);
  };

  // Determine Title based on Account Type
  const getTitle = () => {
      if (view === 'SELECTION') return t.login.selectType;
      if (view === 'LOGIN') return t.login.welcomeBack;

      // Register View Custom Titles
      if (accountType === 'BUSINESS') return isAr ? "تسجيل منشأة جديدة" : "Register Business";
      return isAr ? "تسجيل حساب شخصي" : "Register Personal Account";
  };

  return (
    <div className={`min-h-screen w-full flex bg-slate-50 dark:bg-slate-950 transition-colors duration-300 ${isAr ? 'rtl' : 'ltr'}`} dir={isAr ? 'rtl' : 'ltr'}>

      {/* Floating Language Switcher */}
      <div className={`fixed top-6 ${isAr ? 'left-6' : 'right-6'} z-50`}>
          <button 
            onClick={() => onToggleLanguage(isAr ? 'en' : 'ar')}
            className="flex items-center gap-2 bg-white/80 dark:bg-slate-800/80 backdrop-blur-md px-4 py-2 rounded-2xl border border-slate-200 dark:border-slate-700 shadow-xl hover:scale-105 transition-all text-sm font-bold text-slate-700 dark:text-slate-200"
          >
            <Languages size={18} className="text-emerald-500" />
            <span>{isAr ? 'English' : 'العربية'}</span>
          </button>
      </div>

      {/* Visual Side (Hidden on Mobile) */}
      <div className="hidden lg:flex w-1/2 bg-slate-900 relative overflow-hidden items-center justify-center p-12">
        <div 
            className="absolute inset-0 z-0"
            style={{
                backgroundImage: `url('https://images.unsplash.com/photo-1642543492481-44e81e3914a7?q=80&w=2070&auto=format&fit=crop')`, 
                backgroundSize: 'cover',
                backgroundPosition: 'center',
            }}
        />
        <div className="absolute inset-0 bg-gradient-to-br from-slate-900/80 via-emerald-950/60 to-slate-900/80 z-0"></div>
        <div className="relative z-10 text-white max-w-lg backdrop-blur-sm bg-slate-900/40 p-8 rounded-3xl border border-white/20 shadow-2xl">
          <div className="inline-flex items-center gap-2 bg-emerald-500/20 border border-emerald-500/30 px-4 py-1.5 rounded-full text-sm font-semibold text-emerald-300 mb-8 shadow-lg shadow-emerald-900/20">
            <BrainCircuit size={16} />
            <span>{t.aiBadge}</span>
          </div>
          <h1 className="text-5xl font-extrabold mb-6 leading-tight tracking-tight">
            {t.login.heroTitle}
          </h1>
          <p className="text-slate-200 text-lg leading-relaxed font-light">
            {t.login.heroDesc}
          </p>
          <div className="mt-10 flex items-center gap-4 pt-8 border-t border-white/10">
             <div className="flex -space-x-3 rtl:space-x-reverse">
                <div className="w-10 h-10 rounded-full border-2 border-slate-800 bg-slate-600 flex items-center justify-center text-xs font-bold">A</div>
                <div className="w-10 h-10 rounded-full border-2 border-slate-800 bg-emerald-600 flex items-center justify-center text-xs font-bold">F</div>
                <div className="w-10 h-10 rounded-full border-2 border-slate-800 bg-blue-600 flex items-center justify-center text-xs font-bold">M</div>
             </div>
             <div className="text-sm text-slate-300 leading-tight">
                <span className="block text-white font-bold text-base">2,500+</span>
                مؤسسة عمانية تثق بنا
             </div>
          </div>
        </div>
      </div>

      {/* Form Side */}
      <div className="w-full lg:w-1/2 flex items-center justify-center p-8 bg-slate-50 dark:bg-slate-950 h-screen overflow-y-auto">
        <div className="w-full max-w-md space-y-6 my-auto relative">

          {(view === 'LOGIN' || view === 'REGISTER') && (
            <button 
                onClick={handleBack}
                className="absolute -top-12 start-0 text-slate-400 hover:text-slate-600 flex items-center gap-1 text-sm font-bold transition-all"
            >
                <ArrowLeft size={16} className={isAr ? "rotate-180" : ""} />
                <span>{isAr ? "رجوع" : "Back"}</span>
            </button>
          )}

          <div className="text-center lg:text-start">
             <div className={`inline-flex items-center justify-center w-14 h-14 bg-gradient-to-br ${accountType === 'BUSINESS' ? 'from-emerald-500 to-teal-600' : 'from-blue-500 to-indigo-600'} text-white rounded-2xl mb-6 shadow-lg shadow-emerald-500/20 lg:hidden`}>
                {accountType === 'INDIVIDUAL' ? <User size={28} /> : (accountType === 'BUSINESS' ? <Building2 size={28} /> : <Wallet size={28} />)}
             </div>

             {/* Header Section */}
             <>
                <h2 className="text-3xl font-extrabold text-slate-900 dark:text-white tracking-tight">
                    {getTitle()}
                </h2>
                <p className="text-slate-500 dark:text-slate-400 mt-2 text-lg">
                    {view === 'SELECTION' && (isAr ? "اختر نوع الحساب للمتابعة" : "Choose account type to proceed")}
                    {view === 'LOGIN' && t.login.subtitle}
                    {view === 'REGISTER' && (
